import PropTypes from 'prop-types';
import { useState, useRef } from 'react';
import { 
  UploadCloud, 
  FileText, 
  X, 
  AlertTriangle, 
  CheckCircle, 
  Loader2,

  FileCheck
} from 'lucide-react';
import { uploadDocuments } from '../api';

const ALLOWED_TYPES = ['pdf', 'png', 'jpg', 'jpeg', 'tiff'];

export default function FileUploader({ onUploadSuccess }) {
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [errorMessage, setErrorMessage] = useState(null);
  const [successMessage, setSuccessMessage] = useState(null);
  const fileInputRef = useRef(null);

  const getExtension = (filename) => {
    if (!filename || !filename.includes('.')) return '';
    return filename.split('.').pop().toLowerCase();
  };

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;
    setSelectedFiles((prev) => [...prev, ...files]);
    setErrorMessage(null);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    const files = Array.from(e.dataTransfer.files);
    if (!files.length) return;

    setSelectedFiles((prev) => [...prev, ...files]);
    setErrorMessage(null);
  };

  const removeFile = (indexToRemove) => {
    setSelectedFiles((prev) => prev.filter((_, idx) => idx !== indexToRemove));
  };

  const handleUploadSubmit = async () => {
    if (selectedFiles.length === 0) return;

    setIsUploading(true);
    setErrorMessage(null);
    setSuccessMessage(null);
    setUploadProgress(30);

    try {
      setUploadProgress(70);
      const result = await uploadDocuments(selectedFiles);
      setUploadProgress(100);

      if (result && typeof result === 'object') {
        if (result.rejected_count > 0 && result.accepted_count > 0) {
          setErrorMessage(`Upload Warning: ${result.accepted_count} file(s) accepted & queued, ${result.rejected_count} file(s) rejected.`);
        } else if (result.accepted_count > 0) {
          setSuccessMessage(`Successfully validated and queued ${result.accepted_count} file(s)!`);
        } else if (result.rejected_count > 0) {
          setErrorMessage(`All ${result.rejected_count} file(s) were rejected.`);
        }
      }

      setSelectedFiles([]);
      if (fileInputRef.current) fileInputRef.current.value = '';

      if (onUploadSuccess) {
        onUploadSuccess(result);
      }
    } catch (err) {
      console.error('Upload Error:', err);
      let detail;
      if (err.response?.data?.detail) {
        // Server responded with a structured error (validation failure, etc.)
        detail = err.response.data.detail;
      } else if (err.code === 'ERR_NETWORK' || err.code === 'ERR_CONNECTION_REFUSED' || !err.response) {
        detail = 'Cannot reach the server. Please ensure the backend is running and reachable, then try again.';
      } else {
        detail = `Upload failed (HTTP ${err.response?.status ?? 'unknown'}). Please verify file integrity and server state.`;
      }
      setErrorMessage(detail);
    } finally {
      setIsUploading(false);
      setTimeout(() => setUploadProgress(0), 800);
    }
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 B';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(2) + ' MB';
  };

  return (
    <div className="bg-surface-container rounded-2xl border border-outline-variant/20 overflow-hidden mb-8">
      <div className="p-6 border-b border-outline-variant/10 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-headline-lg font-headline-lg text-on-surface mb-1">Upload Clinical Documents</h3>
          <p className="text-body-md font-body-md text-on-surface-variant">
            Validation Service checks extension, MIME type, file size (&lt;20MB), and PDF/Image readability before queueing.
          </p>
        </div>
        <div className="px-3 py-1.5 rounded-md bg-surface-variant border border-outline-variant/30 text-label-caps font-label-caps text-secondary shrink-0">
          Validation Engine
        </div>
      </div>

      {errorMessage && (
        <div className="mx-6 mt-6 px-4 py-3 rounded-lg bg-error-container/10 border border-error/30 text-error flex justify-between items-center text-sm">
          <div className="flex items-center gap-2">
            <AlertTriangle size={18} />
            <span>{errorMessage}</span>
          </div>
          <button className="text-error/80 hover:text-error" onClick={() => setErrorMessage(null)}><X size={16} /></button>
        </div>
      )}

      {successMessage && (
        <div className="mx-6 mt-6 px-4 py-3 rounded-lg bg-emerald-500/10 border border-emerald-500/30 text-emerald-500 flex justify-between items-center text-sm">
          <div className="flex items-center gap-2">
            <CheckCircle size={18} />
            <span>{successMessage}</span>
          </div>
          <button className="text-emerald-500/80 hover:text-emerald-500" onClick={() => setSuccessMessage(null)}><X size={16} /></button>
        </div>
      )}
      {/* Drag & Drop Zone */}
      <div className="p-6 md:p-10">
        <div
          className={`border-2 border-dashed rounded-2xl bg-surface-container-highest/30 transition-colors duration-300 group cursor-pointer flex flex-col items-center justify-center py-16 px-6 text-center ${
            isDragging ? 'border-primary/80 bg-primary/5' : 'border-outline-variant/50 hover:border-secondary/60'
          }`}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
        >
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileSelect}
            multiple
            accept=".pdf,.png,.jpg,.jpeg,.tiff,.docx,.doc,.xls,.xlsx,.zip,.rar,.exe,.mp4,.mov"
            style={{ display: 'none' }}
          />

          <div className="w-20 h-20 rounded-full bg-secondary-container/20 border border-secondary/30 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300 shadow-[0_0_20px_rgba(37,99,235,0.2)]">
            <UploadCloud className="text-4xl text-secondary w-10 h-10" />
          </div>

          <h4 className="text-headline-md font-headline-md text-on-surface mb-2">Drag & drop patient records here</h4>
          <p className="text-body-lg font-body-lg text-on-surface-variant mb-8">or click to browse your filesystem (bulk & mixed uploads supported)</p>

          <div className="flex flex-wrap justify-center gap-3">
            <span className="px-3 py-1 rounded bg-surface-variant text-label-caps font-label-caps text-on-surface-variant border border-outline-variant/20">PDF</span>
            <span className="px-3 py-1 rounded bg-surface-variant text-label-caps font-label-caps text-on-surface-variant border border-outline-variant/20">PNG</span>
            <span className="px-3 py-1 rounded bg-surface-variant text-label-caps font-label-caps text-on-surface-variant border border-outline-variant/20">JPG</span>
            <span className="px-3 py-1 rounded bg-surface-variant text-label-caps font-label-caps text-on-surface-variant border border-outline-variant/20">JPEG</span>
            <span className="px-3 py-1 rounded bg-surface-variant text-label-caps font-label-caps text-on-surface-variant border border-outline-variant/20">TIFF</span>
          </div>
        </div>
      </div>

      {/* Upload Progress Bar */}
      {isUploading && (
        <div className="h-1.5 w-full bg-outline-variant/30 overflow-hidden">
          <div 
            className="h-full bg-gradient-to-r from-primary to-secondary transition-all duration-300" 
            style={{ width: `${uploadProgress}%` }} 
          />
        </div>
      )}

      {/* Selected File List */}
      {selectedFiles.length > 0 && (
        <div className="px-6 md:px-10 pb-10">
          <div className="text-sm font-semibold text-on-surface-variant mb-3">
            Files Ready for Validation & Upload ({selectedFiles.length})
          </div>
          <div className="flex flex-col gap-3">
            {selectedFiles.map((file, idx) => {
              const ext = getExtension(file.name);
              const isSupported = ALLOWED_TYPES.includes(ext);
              return (
                <div key={idx} className={`flex items-center justify-between p-3 rounded-xl border ${
                  isSupported ? 'bg-surface-variant/40 border-outline-variant/40' : 'bg-error-container/5 border-error/30'
                }`}>
                  <div className="flex items-center gap-3">
                    <FileText size={20} className={isSupported ? 'text-primary' : 'text-error'} />
                    <div>
                      <div className={`text-sm font-medium ${isSupported ? 'text-on-surface' : 'text-error/90'}`}>
                        {file.name} {!isSupported && <span className="text-error text-xs ml-2">(Will be rejected)</span>}
                      </div>
                      <div className="text-xs text-on-surface-variant/70">
                        {formatFileSize(file.size)} • {ext.toUpperCase() || 'UNKNOWN'}
                      </div>
                    </div>
                  </div>
                  <button
                    type="button"
                    className="p-1.5 rounded-md text-on-surface-variant hover:text-error hover:bg-error-container/10 transition-colors"
                    onClick={(e) => { e.stopPropagation(); removeFile(idx); }}
                    disabled={isUploading}
                  >
                    <X size={18} />
                  </button>
                </div>
              );
            })}
          </div>

          <div className="flex justify-end gap-4 mt-6">
            <button
              type="button"
              className="px-5 py-2.5 rounded-lg font-semibold text-sm bg-surface-variant border border-outline-variant/30 text-on-surface hover:bg-surface-variant/80 transition-colors"
              onClick={() => { setSelectedFiles([]); if (fileInputRef.current) fileInputRef.current.value = ''; }}
              disabled={isUploading}
            >
              Clear All
            </button>
            <button
              type="button"
              className="px-5 py-2.5 rounded-lg font-semibold text-sm bg-gradient-to-r from-primary to-secondary text-white shadow-lg shadow-primary/20 hover:opacity-90 transition-all flex items-center gap-2 disabled:opacity-50"
              onClick={handleUploadSubmit}
              disabled={isUploading}
            >
              {isUploading ? (
                <>
                  <Loader2 size={18} className="animate-spin" />
                  Validating & Ingesting...
                </>
              ) : (
                `Validate & Upload ${selectedFiles.length} File${selectedFiles.length > 1 ? 's' : ''}`
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

FileUploader.propTypes = {
  onUploadSuccess: PropTypes.any
};

import PropTypes from 'prop-types';
import { useState, useEffect } from 'react';
import { X, Search, UserPlus } from 'lucide-react';
import apiClient from '../api';

export default function LinkPatientModal({ isOpen, onClose, onLink, documentId, suggestedPatientData = {} }) {
  const generateMRN = () => {
    const d = new Date();
    const dateStr = d.toISOString().split('T')[0].replace(/-/g, '');
    const rand = Math.floor(1000 + Math.random() * 9000);
    return `MRN-${dateStr}-${rand}`;
  };

  const [tab, setTab] = useState('search');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);

  // Create form state
  const [formData, setFormData] = useState({
    mrn: '',
    name: '',
    dob: '',
    sex: ''
  });

  useEffect(() => {
    if (isOpen) {
      setSearchQuery(suggestedPatientData.mrn || suggestedPatientData.name || '');
      setFormData({
        mrn: generateMRN(),
        name: suggestedPatientData.name || '',
        dob: suggestedPatientData.dob || '',
        sex: suggestedPatientData.sex || ''
      });
    }
  }, [isOpen]); // Only run once when modal opens

  useEffect(() => {
    if (isOpen && tab === 'search' && searchQuery) {
      handleSearch();
    }
  }, [isOpen, tab]);

  if (!isOpen) return null;

  const handleSearch = async () => {
    if (!searchQuery) return;
    setIsSearching(true);
    try {
      const res = await apiClient.get('/patients', { params: { search: searchQuery } });
      setSearchResults(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleCreateAndLink = async (e) => {
    e.preventDefault();
    onLink({
      create_new: true,
      mrn: formData.mrn,
      name: formData.name,
      dob: formData.dob,
      sex: formData.sex
    });
  };

  return (
    <div className="modal-backdrop">
      <div className="modal-content" style={{ width: '450px' }}>
        <div className="modal-header">
          <h3>Link to Patient</h3>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>

        <div className="modal-tabs">
          <button 
            className={`tab-btn ${tab === 'search' ? 'active' : ''}`}
            onClick={() => setTab('search')}
          >
            <Search size={14} /> Search Existing
          </button>
          <button 
            className={`tab-btn ${tab === 'create' ? 'active' : ''}`}
            onClick={() => setTab('create')}
          >
            <UserPlus size={14} /> Create New
          </button>
        </div>

        <div className="modal-body">
          {tab === 'search' ? (
            <div>
              <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem' }}>
                <input 
                  type="text" 
                  className="input-field" 
                  style={{ flex: 1 }}
                  placeholder="Search by MRN (or Name)..." 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                />
                <button className="btn btn-primary" onClick={handleSearch} disabled={isSearching}>
                  Search
                </button>
              </div>
              <div className="search-results">
                {isSearching ? <p>Searching...</p> : searchResults.length === 0 ? (
                  <p style={{ color: 'var(--text-dim)' }}>No patients found.</p>
                ) : (
                  searchResults.map(p => (
                    <div key={p.patient_id} className="patient-card" style={{ padding: '0.75rem', border: '1px solid var(--border-color)', borderRadius: '6px', marginBottom: '0.5rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div>
                        <strong>{p.name}</strong> <span style={{ color: 'var(--text-dim)', fontSize: '0.85em' }}>({p.mrn})</span>
                        <div style={{ fontSize: '0.85em', color: 'var(--text-dim)' }}>DOB: {p.dob || 'N/A'}</div>
                      </div>
                      <button className="btn btn-secondary" onClick={() => onLink({ patient_id: p.patient_id })}>
                        Link
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>
          ) : (
            <form onSubmit={handleCreateAndLink}>
              <div className="form-group" style={{ marginBottom: '1rem' }}>
                <label>MRN *</label>
                <input type="text" className="input-field" required value={formData.mrn} onChange={e => setFormData({...formData, mrn: e.target.value})} />
              </div>
              <div className="form-group" style={{ marginBottom: '1rem' }}>
                <label>Full Name *</label>
                <input type="text" className="input-field" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="form-group" style={{ marginBottom: '1rem' }}>
                <label>Date of Birth</label>
                <input type="date" className="input-field" value={formData.dob} onChange={e => setFormData({...formData, dob: e.target.value})} />
              </div>
              <div className="form-group" style={{ marginBottom: '1rem' }}>
                <label>Sex</label>
                <select className="input-field" value={formData.sex} onChange={e => setFormData({...formData, sex: e.target.value})}>
                  <option value="">Select...</option>
                  <option value="Male">Male</option>
                  <option value="Female">Female</option>
                  <option value="Other">Other</option>
                </select>
              </div>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.5rem', marginTop: '1.5rem' }}>
                <button type="button" className="btn btn-secondary" onClick={onClose}>Cancel</button>
                <button type="submit" className="btn btn-primary">Create & Link</button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}

LinkPatientModal.propTypes = {
  isOpen: PropTypes.any,
  onClose: PropTypes.any,
  onLink: PropTypes.any,
  documentId: PropTypes.any,
  suggestedPatientData: PropTypes.any
};

import PropTypes from 'prop-types';
import { useState, useEffect, useRef } from 'react';
import {
  CheckCircle2,
  XCircle,
  Edit3,
  ChevronLeft,
  ChevronRight,
  AlertTriangle,
  FileText,
  Zap,
} from 'lucide-react';
import LinkPatientModal from './LinkPatientModal';
import DynamicJSONEditor from './DynamicJSONEditor';
import apiClient from '../api';

const COMPLEX_FIELDS = [
  'vitals', 'diagnosis', 'medications', 'lab_results',
  'patient_identifier', 'ordering_physician', 'symptoms', 'procedures', 'patient_assignment'
];

export default function ReviewFieldCard({
  item,
  index,
  total,
  onAccept,
  onReject,
  onPrev,
  onNext,
  isSubmitting,
}) {
  const [editMode, setEditMode] = useState(false);
  const [editValue, setEditValue] = useState('');
  const [isLinkModalOpen, setIsLinkModalOpen] = useState(false);
  const editRef = useRef(null);

  useEffect(() => {
    setEditMode(false);
    setEditValue(item?.extracted_value ?? '');
  }, [item?.id]);

  useEffect(() => {
    if (editMode && editRef.current) {
      editRef.current.focus();
      editRef.current.select();
    }
  }, [editMode]);

  useEffect(() => {
    const handler = (e) => {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable) return;
      if (isSubmitting) return;

      switch (e.key.toLowerCase()) {
        case 'a':
        case ' ':
          e.preventDefault();
          onAccept(null);
          break;
        case 'r':
          e.preventDefault();
          onReject();
          break;
        case 'e':
          e.preventDefault();
          setEditMode(true);
          break;
        case 'arrowleft':
          e.preventDefault();
          onPrev();
          break;
        case 'arrowright':
          e.preventDefault();
          onNext();
          break;
        default:
          break;
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [isSubmitting, onAccept, onReject, onPrev, onNext]);

  if (!item) return null;

  const conf = item.confidence_score;
  const confPct = (conf * 100).toFixed(1);

  let confColorClass = 'text-emerald-500';
  let confBgClass = 'bg-emerald-500';
  let confBorderClass = 'border-emerald-500/30';
  let confContainerClass = 'bg-emerald-500/10';
  let confLabel = 'High';

  if (conf < 0.5) {
    confColorClass = 'text-error';
    confBgClass = 'bg-error';
    confBorderClass = 'border-error/30';
    confContainerClass = 'bg-error-container/20';
    confLabel = 'Low';
  } else if (conf < 0.8) {
    confColorClass = 'text-amber-500';
    confBgClass = 'bg-amber-500';
    confBorderClass = 'border-amber-500/30';
    confContainerClass = 'bg-amber-500/10';
    confLabel = 'Medium';
  }

  const progressPct = total > 0 ? ((index + 1) / total) * 100 : 0;

  const handleEditSubmit = () => {
    onAccept(editValue.trim() !== (item.extracted_value ?? '').trim() ? editValue.trim() : null);
    setEditMode(false);
  };

  const handleLinkPatient = async (payload) => {
    if (payload.create_new) {
      try {
        const res = await apiClient.post('/patients', {
          mrn: payload.mrn,
          name: payload.name,
          dob: payload.dob,
          sex: payload.sex
        });
        onAccept(res.data.patient_id);
      } catch (err) { console.error(err);
        alert(err.response?.data?.detail || 'Failed to create patient');
      }
    } else {
      onAccept(payload.patient_id);
    }
  };

  const isPatientAssignment = item.field_name === 'patient_assignment';
  let parsedAssignment = null;
  if (isPatientAssignment && item.extracted_value) {
    try { parsedAssignment = JSON.parse(item.extracted_value); } catch(e) {}
  }

  return (
    <div className="flex flex-col h-full bg-surface-container rounded-2xl border border-outline-variant/20 overflow-hidden">

      {/* Top Banner: Document Ref */}
      <div className="flex justify-between items-center px-4 py-2 bg-surface-container-high border-b border-outline-variant/10">
        <div className="flex items-center gap-2">
          <FileText size={14} className="text-on-surface-variant" />
          <span className="text-sm font-semibold text-on-surface truncate max-w-[200px]">{item.document_filename || item.document_id}</span>
        </div>
        <span className="px-2 py-0.5 rounded text-[10px] font-bold text-on-surface-variant bg-surface-variant uppercase border border-outline-variant/20">
          {item.document_filetype || 'DOC'}
        </span>
      </div>

      <div className="p-5 flex-grow flex flex-col">
        {/* Progress Header */}
        <div className="flex justify-between items-end mb-2">
          <div className="text-sm font-semibold text-on-surface">Field {index + 1} of {total}</div>
          <div className="text-xs text-on-surface-variant">{total - index - 1} remaining</div>
        </div>

        {/* Progress Bar */}
        <div className="h-1.5 w-full bg-outline-variant/20 rounded-full overflow-hidden mb-6">
          <div className="h-full bg-primary transition-all duration-300" style={{ width: `${progressPct}%` }}></div>
        </div>

        {/* Field Name & Confidence */}
        <div className="flex justify-between items-start mb-4">
          <h2 className="text-title-lg font-title-lg text-on-surface">{item.field_name}</h2>

          <div className={`flex items-center gap-2 px-2.5 py-1 rounded-full border ${confBorderClass} ${confContainerClass}`}>
            <span className={`w-2 h-2 rounded-full ${confBgClass}`}></span>
            <span className={`text-xs font-bold ${confColorClass}`}>{confPct}%</span>
            <span className={`text-[10px] font-semibold ${confColorClass} uppercase opacity-80`}>{confLabel}</span>
          </div>
        </div>

        {/* Confidence Bar underneath */}
        <div className="h-1 w-full bg-outline-variant/10 rounded-full overflow-hidden mb-6">
          <div className={`h-full ${confBgClass}`} style={{ width: `${confPct}%` }}></div>
        </div>

        {/* Value Section */}
        <div className="flex-grow flex flex-col mb-6">
          <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-2">
            {editMode ? 'Corrected Value' : (isPatientAssignment ? 'Extracted Patient Info' : 'Extracted Value')}
          </label>

          <div className="flex-grow flex flex-col bg-surface-container-highest/20 rounded-xl border border-outline-variant/10 p-4 min-h-[120px]">
            {isPatientAssignment ? (
              <div className="flex flex-col justify-between h-full">
                {parsedAssignment ? (
                  <div className="text-sm text-on-surface space-y-1 mb-4">
                    <div><span className="font-semibold text-on-surface-variant">Name:</span> {parsedAssignment.name || 'N/A'}</div>
                    <div><span className="font-semibold text-on-surface-variant">DOB:</span> {parsedAssignment.dob || 'N/A'}</div>
                    <div><span className="font-semibold text-on-surface-variant">Gender:</span> {parsedAssignment.gender || 'N/A'}</div>
                  </div>
                ) : (
                  <em className="text-on-surface-variant/70 text-sm mb-4 block">No patient info extracted</em>
                )}
                <button 
                  className="mt-auto py-2.5 w-full bg-primary text-on-primary rounded-lg font-semibold hover:bg-primary/90 transition-colors disabled:opacity-50"
                  onClick={() => setIsLinkModalOpen(true)}
                  disabled={isSubmitting}
                >
                  Assign Patient
                </button>
                <LinkPatientModal 
                  isOpen={isLinkModalOpen}
                  onClose={() => setIsLinkModalOpen(false)}
                  documentId={item.document_id}
                  suggestedPatientData={{
                    name: parsedAssignment?.name || '',
                    dob: parsedAssignment?.dob || '',
                    sex: parsedAssignment?.gender || '',
                    mrn: parsedAssignment?.patient_id || ''
                  }}
                  onLink={handleLinkPatient}
                />
              </div>
            ) : editMode ? (
              COMPLEX_FIELDS.includes(item.field_name) ? (
                <div className="flex-grow">
                  <DynamicJSONEditor
                    initialValue={item.extracted_value ?? ''}
                    fieldName={item.field_name}
                    onChange={setEditValue}
                    onSubmit={handleEditSubmit}
                    onCancel={() => {
                      setEditMode(false);
                      setEditValue(item.extracted_value ?? '');
                    }}
                  />
                </div>
              ) : (
                <textarea
                  ref={editRef}
                  className="w-full flex-grow bg-surface-container border border-outline-variant/40 rounded-lg p-3 text-on-surface text-sm focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary resize-none"
                  value={editValue}
                  onChange={(e) => setEditValue(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleEditSubmit();
                    }
                    if (e.key === 'Escape') {
                      setEditMode(false);
                      setEditValue(item.extracted_value ?? '');
                    }
                  }}
                  placeholder="Enter corrected value…"
                />
              )
            ) : (
              <div className="text-base text-on-surface leading-relaxed break-words whitespace-pre-wrap font-medium">
                {item.extracted_value ?? <em className="text-on-surface-variant/50">null / not extracted</em>}
              </div>
            )}
          </div>
        </div>

        {/* Confidence Warning */}
        {conf < 0.5 && (
          <div className="flex items-center gap-2 px-4 py-3 bg-error-container/10 border border-error/30 rounded-lg text-error text-sm font-medium mb-6">
            <AlertTriangle size={16} />
            <span>Low confidence — please verify carefully against the document image.</span>
          </div>
        )}

        {/* Action Buttons */}
        {isPatientAssignment ? null : editMode ? (
          <div className="flex gap-3 mb-6">
            <button
              className="flex-1 flex items-center justify-center gap-2 py-2.5 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg font-semibold transition-colors disabled:opacity-50"
              onClick={handleEditSubmit}
              disabled={isSubmitting}
              title="Submit correction and approve (Enter)"
            >
              <CheckCircle2 size={18} /> Submit Edit
            </button>
            <button
              className="flex-1 flex items-center justify-center gap-2 py-2.5 bg-surface-variant hover:bg-surface-variant/80 text-on-surface rounded-lg font-semibold border border-outline-variant/30 transition-colors disabled:opacity-50"
              onClick={() => { setEditMode(false); setEditValue(item.extracted_value ?? ''); }}
              disabled={isSubmitting}
              title="Cancel edit (Esc)"
            >
              <XCircle size={18} /> Cancel
            </button>
          </div>
        ) : (
          <div className="flex gap-2 mb-6">
            <button
              className="flex-1 flex flex-col items-center justify-center py-3 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-500 rounded-xl border border-emerald-500/30 transition-colors disabled:opacity-50 group"
              onClick={() => onAccept(null)}
              disabled={isSubmitting}
              title="Accept extracted value (A)"
            >
              <div className="flex items-center gap-1.5 font-bold mb-1"><CheckCircle2 size={18} /> Accept</div>
              <kbd className="text-[10px] font-mono px-1.5 py-0.5 bg-emerald-500/20 rounded border border-emerald-500/30 group-hover:bg-emerald-500 group-hover:text-white transition-colors">A</kbd>
            </button>
            <button
              className="flex-1 flex flex-col items-center justify-center py-3 bg-primary/10 hover:bg-primary/20 text-primary rounded-xl border border-primary/30 transition-colors disabled:opacity-50 group"
              onClick={() => setEditMode(true)}
              disabled={isSubmitting}
              title="Edit value then approve (E)"
            >
              <div className="flex items-center gap-1.5 font-bold mb-1"><Edit3 size={18} /> Edit</div>
              <kbd className="text-[10px] font-mono px-1.5 py-0.5 bg-primary/20 rounded border border-primary/30 group-hover:bg-primary group-hover:text-white transition-colors">E</kbd>
            </button>
            <button
              className="flex-1 flex flex-col items-center justify-center py-3 bg-error-container/10 hover:bg-error-container/20 text-error rounded-xl border border-error/30 transition-colors disabled:opacity-50 group"
              onClick={onReject}
              disabled={isSubmitting}
              title="Reject this field (R)"
            >
              <div className="flex items-center gap-1.5 font-bold mb-1"><XCircle size={18} /> Reject</div>
              <kbd className="text-[10px] font-mono px-1.5 py-0.5 bg-error/20 rounded border border-error/30 group-hover:bg-error group-hover:text-white transition-colors">R</kbd>
            </button>
          </div>
        )}

        {/* Navigation */}
        <div className="flex items-center justify-between pt-4 border-t border-outline-variant/10">
          <button
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-semibold text-on-surface-variant hover:text-on-surface hover:bg-surface-variant transition-colors disabled:opacity-30 disabled:hover:bg-transparent group"
            onClick={onPrev}
            disabled={index === 0 || isSubmitting}
          >
            <ChevronLeft size={16} /> Prev <kbd className="hidden sm:inline-block text-[10px] font-mono px-1 border border-outline-variant/30 rounded ml-1 group-hover:bg-surface-variant group-hover:border-outline-variant">←</kbd>
          </button>

          <div className="flex gap-1 items-center">
            {Array.from({ length: Math.min(total, 7) }).map((_, i) => {
              const isActive = i === index % 7;
              return (
                <div 
                  key={i} 
                  className={`w-1.5 h-1.5 rounded-full transition-colors ${isActive ? 'bg-primary scale-125' : 'bg-outline-variant/30'}`}
                />
              );
            })}
            {total > 7 && <span className="text-[10px] font-bold text-on-surface-variant ml-1">+{total - 7}</span>}
          </div>

          <button
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-semibold text-on-surface-variant hover:text-on-surface hover:bg-surface-variant transition-colors disabled:opacity-30 disabled:hover:bg-transparent group"
            onClick={onNext}
            disabled={index >= total - 1 || isSubmitting}
          >
            <kbd className="hidden sm:inline-block text-[10px] font-mono px-1 border border-outline-variant/30 rounded mr-1 group-hover:bg-surface-variant group-hover:border-outline-variant">→</kbd> Next <ChevronRight size={16} />
          </button>
        </div>
      </div>

      {/* Keyboard Hint Footer */}
      <div className="bg-surface-container-high py-2 px-4 border-t border-outline-variant/10 flex items-center justify-center gap-1.5 text-xs font-medium text-on-surface-variant">
        <Zap size={14} className="text-primary" />
        <span>Keyboard:</span>
        <kbd className="px-1 py-0.5 bg-surface-variant rounded border border-outline-variant/30">Space</kbd> <span>accept</span>
        <span>·</span>
        <kbd className="px-1 py-0.5 bg-surface-variant rounded border border-outline-variant/30">E</kbd> <span>edit</span>
        <span>·</span>
        <kbd className="px-1 py-0.5 bg-surface-variant rounded border border-outline-variant/30">R</kbd> <span>reject</span>
      </div>
    </div>
  );
}

ReviewFieldCard.propTypes = {
  item: PropTypes.any,
  index: PropTypes.any,
  total: PropTypes.any,
  onAccept: PropTypes.any,
  onReject: PropTypes.any,
  onPrev: PropTypes.any,
  onNext: PropTypes.any,
  isSubmitting: PropTypes.any
};

import { NavLink } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { 
  Activity, 
  ClipboardCheck, 

  Users,
  MessageSquare,

  LogOut,
  BarChart2
} from 'lucide-react';

// Source of truth mapping route keys to allowed roles, reflecting backend rbac.py
export const RBAC_MATRIX = {
  intake: ['doctor', 'nurse', 'hospital_admin'],
  review: ['doctor', 'nurse', 'hospital_admin'],
  canonical: ['doctor', 'nurse', 'hospital_admin'],
  patients: ['doctor', 'nurse', 'hospital_admin'],
  patientDashboard: ['doctor', 'hospital_admin'],
  dashboards: ['hospital_admin', 'department_head'],
  policyChat: ['doctor', 'nurse', 'hospital_admin'],
  policyUpload: ['hospital_admin', 'it', 'compliance'],
  patientQA: ['doctor'],
  reports: ['doctor', 'hospital_admin'],
};

const hasAccess = (role, routeKey) => {
  return RBAC_MATRIX[routeKey]?.includes(role.toLowerCase());
};

