        {hasAccess(user.role, 'policyChat') && (
          <NavLink to="/policy-assistant" className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}>
            <MessageSquare size={18} />
            <span>Policy Assistant</span>
          </NavLink>
        )}
      </nav>

      <div className="sidebar-footer">
        <div className="user-profile">
          <div className="user-info">
            <span className="user-email">{user.email}</span>
            <span className="user-role">{user.role}</span>
          </div>
          <button onClick={logout} className="logout-btn" title="Logout">
            <LogOut size={16} />
          </button>
        </div>
      </div>
    </aside>
  );
}

import { useState } from 'react';
import { BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, ResponsiveContainer, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';
import { BarChart2, Search, RotateCcw, Loader2, AlertTriangle, Filter } from 'lucide-react';
import apiClient from '../api';

const COLORS = ['#22c55e', '#38bdf8', '#f59e0b', '#a78bfa', '#f472b6', '#fb7185'];

export default function NaturalLanguageReportPage() {
  const [request, setRequest] = useState('');
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [lastRequest, setLastRequest] = useState('');

  const generate = async (event, queryStr) => {
    if (event) event.preventDefault();
    const query = queryStr || request;
    if (!query.trim()) return;
    setLoading(true); setError(''); setReport(null);
    setLastRequest(query);
    try {
      const response = await apiClient.post('/reports/generate', { nl_query: query });
      setReport(response.data);
    } catch (err) {
      setReport(null);
      setError(err.response?.data?.detail || 'Unable to generate the report. Please try again.');
    } finally { setLoading(false); }
  };

  const renderChart = () => {
    if (!report) return null;
    const data = report.data || [];
    if (!data.length) return <div className="text-on-surface-variant p-8 text-center bg-surface-container rounded-lg border border-outline-variant/20 mt-4">No matching canonical records found for the given criteria.</div>;

    if (report.chart_type === 'pie') return <div className="mt-4"><ResponsiveContainer width="100%" height={350}><PieChart><Pie data={data} dataKey="count" nameKey="label" outerRadius={120} label>{data.map((entry, i) => <Cell key={`${entry.label}-${i}`} fill={COLORS[i % COLORS.length]} />)}</Pie><Tooltip contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }} /></PieChart></ResponsiveContainer></div>;

    if (report.chart_type === 'line') return <div className="mt-4"><ResponsiveContainer width="100%" height={350}><LineChart data={data} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.5} /><XAxis dataKey="label" stroke="#94a3b8" tick={{ fill: '#94a3b8' }} /><YAxis stroke="#94a3b8" tick={{ fill: '#94a3b8' }} /><Tooltip contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }} /><Line type="monotone" dataKey="count" stroke="#38bdf8" strokeWidth={3} dot={{ r: 4, fill: '#38bdf8' }} /></LineChart></ResponsiveContainer></div>;

    return <div className="mt-4"><ResponsiveContainer width="100%" height={350}><BarChart data={data} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}><CartesianGrid strokeDasharray="3 3" stroke="#334155" opacity={0.5} /><XAxis dataKey="label" stroke="#94a3b8" tick={{ fill: '#94a3b8' }} /><YAxis stroke="#94a3b8" tick={{ fill: '#94a3b8' }} /><Tooltip contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }} /><Bar dataKey="count" fill="#38bdf8" radius={[4, 4, 0, 0]}><Cell fill="#38bdf8" /></Bar></BarChart></ResponsiveContainer></div>;
  };

  const renderQueryPlan = () => {
    if (!report?.query_plan) return null;
    const plan = report.query_plan;

    return (
      <div className="flex flex-col gap-3 mt-4">
        <div className="grid grid-cols-2 gap-3 text-sm">
          <div className="bg-surface-container-high p-3 rounded-lg border border-outline-variant/30">
            <span className="text-on-surface-variant text-xs font-bold uppercase tracking-wider block mb-1">Cohort Scope</span>
            <span className="text-on-surface font-medium">{plan.cohort || 'All Patients'}</span>
          </div>
          <div className="bg-surface-container-high p-3 rounded-lg border border-outline-variant/30">
            <span className="text-on-surface-variant text-xs font-bold uppercase tracking-wider block mb-1">Metric</span>
            <span className="text-on-surface font-medium capitalize">{plan.metric || 'Count'}</span>
          </div>
          <div className="bg-surface-container-high p-3 rounded-lg border border-outline-variant/30">
            <span className="text-on-surface-variant text-xs font-bold uppercase tracking-wider block mb-1">Date Range</span>
            <span className="text-on-surface font-medium">{plan.date_range || 'All Time'}</span>
          </div>
          <div className="bg-surface-container-high p-3 rounded-lg border border-outline-variant/30">
            <span className="text-on-surface-variant text-xs font-bold uppercase tracking-wider block mb-1">Grouping</span>
            <span className="text-on-surface font-medium capitalize">{plan.grouping || 'None'}</span>
          </div>
        </div>

        {plan.filters && Object.keys(plan.filters).length > 0 && (
          <div className="bg-surface-container-high p-3 rounded-lg border border-outline-variant/30">
            <span className="text-on-surface-variant text-xs font-bold uppercase tracking-wider flex items-center gap-1.5 mb-2">
              <Filter size={14} /> Explicit Filters
            </span>
            <div className="flex flex-wrap gap-2">
              {Object.entries(plan.filters).map(([k, v]) => (
                <span key={k} className="px-2 py-1 bg-primary/10 border border-primary/20 text-primary rounded-md text-xs font-medium">
                  {k}: {v}
                </span>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="app-container flex flex-col min-h-0">
      <header className="app-header shrink-0">
        <div className="brand-wrapper">
          <div className="brand-logo" style={{ background: 'linear-gradient(135deg, var(--accent-emerald), var(--primary-cyan))' }}>
            <BarChart2 size={26} color="#ffffff" />
          </div>
          <div className="brand-title">
            <h1>Natural-Language Reports</h1>
            <p>Generate clinical analytics using plain text queries</p>
          </div>
        </div>
      </header>

      <form onSubmit={(e) => generate(e, request)} className="bg-surface-container rounded-xl border border-outline-variant/30 p-4 mb-6 flex gap-3 shadow-sm shrink-0">
        <input 
          aria-label="Report request" 
          value={request} 
          onChange={(e) => setRequest(e.target.value)} 
          placeholder="e.g. show me the distribution of diagnoses for diabetic patients" 
          className="flex-1 bg-surface-container-high border border-outline-variant/40 rounded-lg px-4 py-3 text-on-surface focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary shadow-inner"
          disabled={loading}
        />
        <button 
          type="submit" 
          disabled={loading || !request.trim()} 
          className="px-6 py-3 bg-gradient-to-r from-primary to-secondary text-white rounded-lg font-bold flex items-center justify-center gap-2 hover:opacity-90 disabled:opacity-50 transition-opacity"
        >
          {loading ? <Loader2 size={18} className="animate-spin" /> : <Search size={18} />}
          {loading ? 'Analyzing...' : 'Generate'}
        </button>
      </form>

      <div className="flex-1 overflow-y-auto">
        {loading && (
          <div className="flex flex-col items-center justify-center py-20 bg-surface-container/50 rounded-xl border border-outline-variant/10">
            <Loader2 size={40} className="animate-spin text-primary mb-4" />
            <h3 className="text-lg font-semibold text-on-surface">Generating Report...</h3>
            <p className="text-sm text-on-surface-variant">Translating query, applying RBAC scopes, and fetching canonical records.</p>
          </div>
        )}

        {error && !loading && (
          <div className="p-5 rounded-xl bg-error-container/20 border border-error/30 text-error flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="flex items-center gap-3">
              <AlertTriangle size={24} className="shrink-0" />
              <span className="font-medium">{error}</span>
            </div>
            <button 
              onClick={() => generate(null, lastRequest)} 
              className="px-4 py-2 bg-error/10 hover:bg-error/20 border border-error/30 text-error rounded-lg font-semibold flex items-center gap-2 transition-colors whitespace-nowrap"
            >
              <RotateCcw size={16} /> Retry Query
            </button>
          </div>
        )}

        {report && !loading && (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 animate-fade-in-up">
            <div className="xl:col-span-2 flex flex-col gap-6">
              <section className="bg-surface-container rounded-xl border border-outline-variant/20 p-6 shadow-sm">
                <h2 className="text-title-md font-title-md text-on-surface mb-2">Report Visualization</h2>
                <div className="text-sm text-on-surface-variant mb-4">
                  Rendered as <span className="font-semibold text-on-surface">{report.chart_type} chart</span>
                </div>
                {renderChart()}
              </section>
            </div>

            <div className="flex flex-col gap-6">
              <section className="bg-surface-container rounded-xl border border-outline-variant/20 p-6 shadow-sm h-full flex flex-col">
                <h2 className="text-title-md font-title-md text-on-surface mb-2">Execution Plan</h2>
                <p className="text-sm text-on-surface-variant mb-4">
                  The LLM generated the following structured execution plan which was safely executed against the backend data access layer.
                </p>
                {renderQueryPlan()}

                <details className="mt-auto pt-6 text-on-surface-variant/70 text-xs">
                  <summary className="cursor-pointer hover:text-on-surface-variant transition-colors font-medium">View Raw JSON Plan</summary>
                  <pre className="mt-3 p-3 bg-surface-container-highest rounded border border-outline-variant/20 overflow-x-auto text-[10px] text-on-surface-variant leading-relaxed">
                    {JSON.stringify(report.query_plan || report.resolved_filters, null, 2)}
                  </pre>
                </details>
              </section>
            </div>
          </div>
        )}

        {!report && !loading && !error && (
          <div className="flex flex-col items-center justify-center py-24 text-center opacity-60">
            <BarChart2 size={64} className="text-on-surface-variant mb-6" />
            <h2 className="text-xl font-bold text-on-surface mb-2">Awaiting Query</h2>
            <p className="text-on-surface-variant max-w-md mx-auto">
              Use natural language to ask questions about your hospital's canonical data.
              Security scopes are automatically applied based on your role.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  Clock,
  ExternalLink,
  Calendar,
  RefreshCw,
  AlertTriangle,
  Pill,
  ShieldAlert,
  MessageCircleQuestion,

  FileText
} from 'lucide-react';
import { useParams, useNavigate, Link } from 'react-router-dom';

import { fetchPatientDashboard, getDocumentFileUrl } from '../api';
import PatientHeaderBanner from '../components/PatientHeaderBanner';
import LabTrendChart from '../components/LabTrendChart';
import { getEventConfig } from '../utils/timelineEventConfig';

export default function PatientDashboardPage() {
  const { patientId } = useParams();
  const navigate = useNavigate();

  const [dashboard, setDashboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [authError, setAuthError] = useState(false);
  const [lastRefreshed, setLastRefreshed] = useState(null);

  const loadData = useCallback(async (isPolling = false) => {
    if (!patientId) {
      setError("No Patient ID provided in route.");
      setLoading(false);
      return;
    }

    if (!isPolling) setLoading(true);
    else setRefreshing(true);

    setError(null);
    setAuthError(false);

    try {
      const data = await fetchPatientDashboard(patientId);
      setDashboard(data);
      setLastRefreshed(new Date());
    } catch (err) {
      console.error('Failed to load dashboard data:', err);
      if (err.response && err.response.status === 403) {
         setAuthError(true);
         setError("You do not have access to this patient's records.");
      } else {
         setError(err.response?.data?.detail || 'Failed to load dashboard. Please check the backend connection.');
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [patientId]);

  useEffect(() => {
    loadData(false);
  }, [loadData]);

  // Auto-refresh every 15 seconds
  useEffect(() => {
    if (authError || !patientId) return;
    const interval = setInterval(() => {
      loadData(true);
    }, 15000);
    return () => clearInterval(interval);
  }, [loadData, authError, patientId]);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] text-on-surface-variant">
        <RefreshCw size={32} className="animate-spin mb-4 text-primary" />
        <p>Loading patient timeline…</p>
      </div>
    );
  }

  if (authError) {
    return (
      <div className="p-6 md:p-8 max-w-[1200px] mx-auto">
        <div className="flex flex-col items-center justify-center min-h-[40vh] bg-error-container/20 border border-error/30 rounded-2xl p-8 text-center">
          <ShieldAlert size={64} className="text-error mb-4" />
          <h2 className="text-headline-sm font-headline-sm text-error mb-2">Access Denied</h2>
          <p className="text-on-surface-variant">You do not have authorization to view the records for Patient ID: <strong>{patientId}</strong></p>
          <button className="mt-6 px-6 py-2 bg-surface-variant text-on-surface rounded-lg font-semibold hover:bg-surface-variant/80 transition-colors" onClick={() => navigate('/patients')}>
            Return to Patients List
          </button>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 md:p-8 max-w-[1200px] mx-auto">
        <div className="p-4 bg-error-container/20 text-error border border-error/30 rounded-xl flex items-center gap-3">
          <AlertTriangle size={24} />
          <span className="font-medium text-sm">{error}</span>
        </div>
      </div>
    );
  }

  if (!dashboard || !dashboard.patient) {
    return null; // Should not reach here unless error was set
  }

  const { patient, allergies, current_medications, lab_trends, other_lab_results, recent_events, total_events } = dashboard;

  return (
    <div className="app-container flex flex-col gap-6">
      <PatientHeaderBanner patient={patient} allergies={allergies} />

      {error && (
        <div className="p-4 bg-error-container/20 text-error border border-error/30 rounded-xl flex items-center gap-3">
          <AlertTriangle size={20} />
          <span className="font-medium text-sm">{error}</span>
        </div>
      )}

      {/* ── Header Controls ── */}
      <header className="app-header">
        <div className="brand-wrapper">
          <div className="brand-logo" style={{ background: 'linear-gradient(135deg, var(--accent-emerald), var(--primary-cyan))' }}>
            <Clock size={26} color="#ffffff" />
          </div>
          <div className="brand-title">
            <h2>Patient Dashboard</h2>
            <p>Clinical overview for today's consult</p>
          </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', flexWrap: 'wrap' }}>
          {lastRefreshed && (
            <span className="text-xs font-medium text-on-surface-variant hidden sm:inline-block">
              Updated {lastRefreshed.toLocaleTimeString()}
            </span>
          )}

          <button
            className="flex items-center gap-2 px-3 py-1.5 bg-primary/10 text-primary border border-primary/20 rounded-lg font-semibold hover:bg-primary/20 transition-colors text-sm"
            onClick={() => navigate(`/patients/${patientId}/ask`)}
          >
            <MessageCircleQuestion size={14} />
            Ask QA
          </button>

          <button
            className="flex items-center gap-2 px-3 py-1.5 bg-secondary/10 text-secondary border border-secondary/20 rounded-lg font-semibold hover:bg-secondary/20 transition-colors text-sm"
            onClick={() => navigate(`/patients/${patientId}/timeline`)}
          >
            <Clock size={14} />
            Full Timeline
          </button>

          <button
            className="flex items-center gap-2 px-3 py-1.5 bg-surface-variant text-on-surface rounded-lg font-semibold hover:bg-surface-variant/80 transition-colors text-sm"
            onClick={() => loadData(false)}
            disabled={refreshing}
          >
            <RefreshCw size={14} className={refreshing ? 'animate-spin' : ''} />
            Refresh
          </button>
        </div>
      </header>

      {/* ── Dashboard Grid ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Left Column: Medications */}
        <div className="bg-surface-container rounded-xl border border-outline-variant/30 p-4 shadow-sm flex flex-col h-[350px]">
          <h3 className="flex items-center gap-2 text-on-surface font-semibold mb-3 border-b border-outline-variant/20 pb-2">
            <Pill size={16} className="text-emerald-500" /> Current Medications
          </h3>
          <div className="overflow-y-auto flex-1 pr-1 custom-scrollbar">
            {current_medications && current_medications.length > 0 ? (
              <ul className="flex flex-col gap-2">
                {current_medications.map(m => (
                  <li key={m.id} className="bg-surface-container-high rounded-lg p-2 text-sm">
                    <div className="text-on-surface font-medium">{m.raw_text}</div>
                    {m.rxnorm_code && <div className="text-xs text-on-surface-variant mt-1">RxNorm: {m.rxnorm_code}</div>}
                  </li>
                ))}
              </ul>
            ) : (
              <p className="text-sm text-on-surface-variant/70 italic text-center mt-4">
                No active medications recorded.
              </p>
            )}
          </div>
        </div>

        {/* Right Column: Lab Trends */}
        <div className="h-[350px]">
          <LabTrendChart labTrends={lab_trends} otherLabResults={other_lab_results} />
        </div>
      </div>

      {/* ── Recent Activity ── */}
      <div className="bg-surface-container rounded-xl border border-outline-variant/30 p-4 shadow-sm flex flex-col mt-2">
        <div className="flex items-center justify-between mb-3 border-b border-outline-variant/20 pb-2">
          <h3 className="flex items-center gap-2 text-on-surface font-semibold">
            <Clock size={16} className="text-primary" /> Recent Activity
          </h3>
          <span className="text-xs font-medium text-on-surface-variant bg-surface-container-highest px-2 py-1 rounded">
            Showing {recent_events?.length || 0} of {total_events || 0} events
          </span>
        </div>

        <div className="flex flex-col gap-3 py-2">
          {!recent_events || recent_events.length === 0 ? (
            <div className="p-8 text-center flex flex-col items-center justify-center">
              <Clock size={40} className="text-on-surface-variant/50 mb-3" />
              <h3 className="text-lg font-semibold text-on-surface mb-1">No events recorded</h3>
              <p className="text-on-surface-variant text-sm">Once documents for this patient pass review and are committed, they will appear here chronologically.</p>
            </div>
          ) : (
            recent_events.map((event, index) => {
              const cfg = getEventConfig(event.event_type || event.field_name);
              const fileUrl = getDocumentFileUrl(event.document_id);

              return (
                <div key={event.event_id || index} className={`bg-surface-container-high rounded-lg border ${cfg.border} p-3 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:bg-surface-container-highest transition-colors shadow-sm`}>
                  <div className="flex flex-col sm:flex-row sm:items-center gap-3">
                    <div className="flex items-center gap-3">
                      <div className={`flex items-center justify-center w-8 h-8 rounded-full ${cfg.containerBg} ${cfg.color} shrink-0`}>
                        {cfg.icon}
                      </div>
                      <div className="flex items-center gap-1.5 text-xs font-semibold text-on-surface-variant bg-surface-variant px-2 py-1 rounded border border-outline-variant/20 whitespace-nowrap">
                        <Calendar size={12} />
                        {event.event_date || 'Unknown Date'}
                      </div>
                    </div>

                    <div className="text-sm font-semibold text-on-surface line-clamp-1" title={event.summary || event.value || event.raw_text}>
                      {event.summary || event.value || event.raw_text || 'Event recorded'}
                    </div>
                  </div>

                  {fileUrl && (
                    <a
                      href={fileUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1.5 px-3 py-1.5 bg-primary/10 hover:bg-primary/20 text-primary rounded-lg font-semibold text-xs transition-colors shrink-0 border border-primary/20"
                    >
                      <ExternalLink size={12} /> View
                    </a>
                  )}
                </div>
              );
            })
          )}
        </div>

        {total_events > 0 && (
          <div className="mt-4 text-center">
            <Link to={`/patients/${patientId}/timeline`} className="inline-flex items-center gap-1 text-sm font-semibold text-primary hover:text-primary-container transition-colors">
              View full timeline &rarr;
            </Link>
          </div>
        )}
      </div>

    </div>
  );
}

import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import {
  ClipboardCheck,
  RefreshCw,
  CheckCircle2,
  Clock,
  AlertTriangle,
  ZoomIn,
  ZoomOut,
  Maximize2,
  RotateCcw,
  InboxIcon,
  FileText,
} from 'lucide-react';
import ReviewFieldCard from '../components/ReviewFieldCard';
import LinkPatientModal from '../components/LinkPatientModal';
import {
  fetchPendingReviews,
  fetchReviewContext,
  submitReviewAction,
  fetchReviewImageBlob,
  fetchDocumentFileBlob,
  fetchDocuments,
} from '../api';

export default function ReviewQueuePage() {
  const [viewMode, setViewMode] = useState('list');
  const [documents, setDocuments] = useState([]);
  const [allItems, setAllItems] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  const [selectedDocId, setSelectedDocId] = useState(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [context, setContext] = useState(null);
  const [isLoadingContext, setIsLoadingContext] = useState(false);

  const [imgSrc, setImgSrc] = useState(null);
  const [imgError, setImgError] = useState(false);
  const [showFullPage, setShowFullPage] = useState(false);
  const [zoom, setZoom] = useState(1.0);
  const [imgLoaded, setImgLoaded] = useState(false);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [toastMsg, setToastMsg] = useState(null);
  const [isLinkModalOpen, setIsLinkModalOpen] = useState(false);

  const patientAssignmentStr = allItems.find(i => i.document_id === selectedDocId && i.field_name === 'patient_assignment')?.extracted_value;
  const patientIdStr = allItems.find(i => i.document_id === selectedDocId && i.field_name === 'patient_identifier')?.extracted_value;

  const suggestedPatientData = useMemo(() => {
    let data = { name: '', mrn: '', dob: '', sex: '' };
    if (patientAssignmentStr) {
      try {
        const parsed = JSON.parse(patientAssignmentStr);
        if (parsed.name) data.name = parsed.name;
        if (parsed.dob) data.dob = parsed.dob;
        if (parsed.gender) data.sex = parsed.gender;
        if (parsed.patient_id) data.mrn = parsed.patient_id;
      } catch (e) {}
    } else if (patientIdStr) {
      try {
        const parsed = JSON.parse(patientIdStr);
        if (parsed.patient_id) data.mrn = parsed.patient_id;
        if (parsed.name) data.name = parsed.name;
      } catch (e) {
        data.name = patientIdStr;
      }
    }
    return data;
  }, [patientAssignmentStr, patientIdStr]);

  const [reviewedToday, setReviewedToday] = useState(0);
  const startTimeRef = useRef(Date.now());
  const [currentTime, setCurrentTime] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [currentItem]);

  const [isClaiming, setIsClaiming] = useState(false);

  const loadQueue = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const [reviewsData, docsData] = await Promise.all([
        fetchPendingReviews(null, 1, 100),
        fetchDocuments()
      ]);
      setAllItems(reviewsData.items || []);
      setDocuments(docsData || []);
    } catch (err) { console.error(err);
      const raw = err.response?.data?.detail;
      let msg = 'Failed to load review queue';
      if (typeof raw === 'string') msg = raw;
      else if (Array.isArray(raw)) msg = raw.map((e) => e.msg || JSON.stringify(e)).join('; ');
      else if (raw) msg = JSON.stringify(raw);
      setError(msg);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadQueue();
  }, [loadQueue]);

  const docItems = useMemo(() => {
    if (selectedDocId === 'ALL') return allItems;
    if (!selectedDocId) return [];
    return allItems.filter((i) => i.document_id === selectedDocId);
  }, [allItems, selectedDocId]);

  useEffect(() => {
    setCurrentIndex((index) => Math.min(index, Math.max(0, docItems.length - 1)));
  }, [docItems.length]);

  const uniqueDocs = [...new Map(allItems.map((i) => [i.document_id, i])).entries()].map(
    ([docId, item]) => {
      const dItems = allItems.filter((x) => x.document_id === docId);
      const isPatientAssignment = dItems.some(x => x.field_name === 'patient_assignment');
      return { 
        docId, 
        count: dItems.length,
        isPatientAssignment
      };
    }
  );

  useEffect(() => {
    if (viewMode === 'review' && selectedDocId && docItems.length === 0) {
      setViewMode('list');
      setSelectedDocId(null);
      setToastMsg({ msg: '🎉 All fields for this document have been reviewed!', type: 'success' });
      setTimeout(() => setToastMsg(null), 2500);
    }
  }, [docItems.length, viewMode, selectedDocId]);

  const currentItem = docItems[currentIndex] || null;

  useEffect(() => {
    if (!currentItem) {
      setContext(null);
      return;
    }

    let cancelled = false;
    const loadContext = async () => {
      setIsLoadingContext(true);
      try {
        const ctx = await fetchReviewContext(currentItem.id);
        if (!cancelled) setContext(ctx);
      } catch (err) { console.error(err);
        if (!cancelled) setContext(null);
      } finally {
        if (!cancelled) setIsLoadingContext(false);
      }
    };

    loadContext();
    return () => { cancelled = true; };
  }, [currentItem?.id]);

  useEffect(() => {
    if (!currentItem) {
      setImgSrc(null);
      return;
    }

    let cancelled = false;
    setImgLoaded(false);
    setImgError(false);

    setImgSrc((prev) => {
      if (prev && prev.startsWith('blob:')) URL.revokeObjectURL(prev);
      return null;
    });

    const loadImage = async () => {
      try {
        const blob = await fetchReviewImageBlob(currentItem.id, showFullPage);
        if (!cancelled) {
          setImgSrc(URL.createObjectURL(blob));
        }
      } catch (err) { console.error(err);
        if (!cancelled) {
          if (currentItem.document_id) {
            try {
              const blob = await fetchDocumentFileBlob(currentItem.document_id);
              if (!cancelled) {
                setImgSrc(URL.createObjectURL(blob));
              }
            } catch (_) {
              if (!cancelled) setImgError(true);
            }
          } else {
            setImgError(true);
          }
        }
      }
    };

    loadImage();

    return () => { cancelled = true; };
  }, [currentItem?.id, showFullPage]);

  const showToast = (msg, type = 'success') => {
    setToastMsg({ msg, type });
    setTimeout(() => setToastMsg(null), 2500);
  };

  const handleAccept = async (correctedValue) => {
    if (!currentItem || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await submitReviewAction(currentItem.id, 'approve', correctedValue, 'reviewer-ui');
      showToast(
        correctedValue !== null
          ? `✏️ "${currentItem.field_name}" corrected & approved`
          : `✅ "${currentItem.field_name}" accepted`
      );
      setReviewedToday((n) => n + 1);
      setAllItems((prev) => prev.filter((i) => i.id !== currentItem.id));
    } catch (err) { console.error(err);
      showToast(err.response?.data?.detail || 'Action failed', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleReject = async () => {
    if (!currentItem || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await submitReviewAction(currentItem.id, 'reject', null, 'reviewer-ui');
      showToast(`❌ "${currentItem.field_name}" rejected`, 'warn');
      setReviewedToday((n) => n + 1);
      setAllItems((prev) => prev.filter((i) => i.id !== currentItem.id));
    } catch (err) { console.error(err);
      showToast(err.response?.data?.detail || 'Action failed', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handlePrev = useCallback(() => setCurrentIndex((i) => Math.max(0, i - 1)), []);
  const handleNext = useCallback(() => setCurrentIndex((i) => Math.min(docItems.length - 1, i + 1)), [docItems.length]);

  const elapsedSec = Math.floor((currentTime - startTimeRef.current) / 1000);
  const elapsedStr =
    elapsedSec >= 60
      ? `${Math.floor(elapsedSec / 60)}m ${elapsedSec % 60}s`
      : `${elapsedSec}s`;

  const bbox = context?.bounding_box;

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] text-on-surface-variant">
        <RefreshCw size={32} className="animate-spin mb-4 text-primary" />
        <p>Loading review queue…</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] text-error">
        <AlertTriangle size={32} className="mb-4" />
        <p>{error}</p>
        <button className="mt-4 px-4 py-2 bg-primary text-on-primary rounded-lg font-semibold hover:bg-primary/90 transition-colors" onClick={loadQueue}>
          Retry
        </button>
      </div>
    );
  }

  // Early return for empty state removed so the header is always rendered.

  return (
    <div className="app-container flex-1 flex flex-col min-h-0">
      {/* Header Section */}
      <header className="app-header">
        <div className="brand-wrapper">
          <div className="brand-logo" style={{ background: 'linear-gradient(135deg, var(--accent-emerald), var(--primary-cyan))' }}>
            <ClipboardCheck size={26} color="#ffffff" />
          </div>
          <div className="brand-title">
            <h1>Pending Review Queue</h1>
            <p>Human-in-the-Loop Verification</p>
          </div>
        </div>

        <div className="flex items-center gap-4 bg-surface-container-high px-4 py-2 rounded-xl border border-outline-variant/20">
          <div className="flex items-center gap-2 text-sm font-semibold">
            <AlertTriangle size={16} className="text-amber-500" />
            <span className="text-on-surface"><span className="text-amber-500">{allItems.length}</span> pending</span>
          </div>
          <div className="w-px h-4 bg-outline-variant/30 mx-2"></div>
          <div className="flex items-center gap-2 text-sm font-semibold">
            <CheckCircle2 size={16} className="text-emerald-500" />
            <span className="text-on-surface"><span className="text-emerald-500">{reviewedToday}</span> reviewed this session</span>
          </div>
          <div className="w-px h-4 bg-outline-variant/30 mx-2"></div>
          <div className="flex items-center gap-2 text-sm text-on-surface-variant font-medium">
            <Clock size={16} />
            <span>{elapsedStr}</span>
          </div>
          <button className="btn btn-icon ml-2" onClick={loadQueue} title="Refresh queue">
            <RefreshCw size={16} />
          </button>
        </div>
      </header>

      {viewMode === 'list' ? (
        <div className="grid gap-4 mt-2">
          {allItems.length === 0 ? (
            <div className="flex flex-col items-center justify-center min-h-[50vh] text-center p-8 bg-surface-container rounded-2xl border border-outline-variant/20 mt-8">
              <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mb-6">
                <InboxIcon size={32} className="text-primary" />
              </div>
              <h2 className="text-headline-md font-headline-md text-on-surface mb-2">Review Queue is Empty</h2>
              <p className="text-body-lg font-body-lg text-on-surface-variant mb-1">All fields are at or above the confidence threshold — no manual review needed.</p>
              <p className="text-sm text-on-surface-variant/70 mb-6">Upload more documents or lower the confidence threshold to populate the queue.</p>
              <button className="flex items-center gap-2 px-4 py-2 bg-surface-variant text-on-surface rounded-lg font-semibold border border-outline-variant/30 hover:bg-surface-variant/80 transition-colors" onClick={loadQueue}>
                <RefreshCw size={16} /> Refresh
              </button>
            </div>
          ) : (
            uniqueDocs.map(({ docId, count, isPatientAssignment }) => {
              const doc = documents.find(d => d.document_id === docId);
              const filename = doc ? doc.filename : (docId.slice(0, 8) + '…');
              return (
                <div key={docId} className="flex justify-between items-center p-5 bg-surface-container rounded-xl border border-outline-variant/20 hover:border-outline-variant/40 transition-colors">
                  <div>
                    <h3 className="flex items-center gap-2 text-lg font-semibold text-on-surface mb-2">
                      <FileText size={20} className="text-primary" />
                      {filename}
                    </h3>
                    <div className="flex gap-4 text-sm font-medium">
                      {isPatientAssignment ? (
                        <span className="flex items-center gap-1.5 text-error">
                          <AlertTriangle size={16} /> Needs Patient Assignment
                        </span>
                      ) : (
                        <span className="flex items-center gap-1.5 text-amber-500">
                          <ZoomIn size={16} /> Low Confidence Data ({count} fields)
                        </span>
                      )}
                    </div>
                  </div>
                  <button 
                    className="px-5 py-2.5 bg-gradient-to-r from-primary to-secondary text-white rounded-lg font-semibold shadow-lg shadow-primary/20 hover:opacity-90 transition-opacity disabled:opacity-50"
                    disabled={isClaiming}
                    onClick={async () => {
                      setIsClaiming(true);
                      setToastMsg({ msg: 'Locking document for review...', type: 'info' });
                      // Simulate a claim request to backend
                      await new Promise(r => setTimeout(r, 600));
                      setIsClaiming(false);
                      setSelectedDocId(docId);
                      setViewMode('review');
                      setToastMsg({ msg: 'Document claimed successfully.', type: 'success' });
                    }}
                  >
                    {isClaiming ? 'Claiming...' : 'Start Review'}
                  </button>
                </div>
              );
            })
          )}
        </div>
      ) : (
        <div className="flex flex-col h-full flex-grow">
          <div className="mb-4">
            <button 
              className="flex items-center gap-2 px-4 py-2 bg-surface-variant text-on-surface rounded-lg font-semibold border border-outline-variant/30 hover:bg-surface-variant/80 transition-colors text-sm"
              onClick={() => {
                if (window.confirm("Return to queue? Any unsaved edits on the current field will be lost.")) {
                  setViewMode('list'); 
                  setSelectedDocId(null);
                }
              }}
            >
              <RotateCcw size={16} className="-rotate-45" /> Back to Queue
            </button>
          </div>

          <LinkPatientModal 
            isOpen={isLinkModalOpen}
            onClose={() => setIsLinkModalOpen(false)}
            documentId={selectedDocId}
            suggestedPatientData={suggestedPatientData}
            onLink={async (payload) => {
              setIsLinkModalOpen(false);
              try {
                const { default: api } = await import('../api');
                await api.post(`/documents/${selectedDocId}/link-patient`, payload);
                setToastMsg({ msg: `Document linked to patient successfully!`, type: 'success' });
                setTimeout(() => setToastMsg(null), 2500);
              } catch (err) { console.error(err);
                setToastMsg({ msg: err.response?.data?.detail || 'Link failed', type: 'error' });
                setTimeout(() => setToastMsg(null), 2500);
              }
            }}
          />

          {/* Split Pane Container */}
          <div className="flex flex-col lg:flex-row gap-6 flex-grow min-h-0">

            {/* Left: Document Image Viewer */}
            <div className="flex flex-col flex-1 bg-surface-container rounded-2xl border border-outline-variant/20 overflow-hidden relative">
              <div className="flex justify-between items-center p-3 border-b border-outline-variant/10 bg-surface-container-high">
                <span className="text-sm font-semibold text-on-surface-variant px-2">
                  {showFullPage ? 'Full Page View' : 'Field Region View'}
                </span>
                <div className="flex items-center gap-1">
                  <button className="p-1.5 rounded text-on-surface-variant hover:bg-surface-variant hover:text-on-surface transition-colors flex items-center gap-1.5 text-xs font-semibold mr-2" onClick={() => setShowFullPage((v) => !v)}>
                    <Maximize2 size={14} /> {showFullPage ? 'Crop to Field' : 'Full Page'}
                  </button>
                  <div className="w-px h-4 bg-outline-variant/30 mx-1"></div>
                  <button className="p-1.5 rounded text-on-surface-variant hover:bg-surface-variant hover:text-on-surface transition-colors" onClick={() => setZoom((z) => Math.min(3, z + 0.25))} disabled={zoom >= 3}>
                    <ZoomIn size={16} />
                  </button>
                  <button className="p-1.5 rounded text-on-surface-variant hover:bg-surface-variant hover:text-on-surface transition-colors" onClick={() => setZoom((z) => Math.max(0.5, z - 0.25))} disabled={zoom <= 0.5}>
                    <ZoomOut size={16} />
                  </button>
                  <button className="p-1.5 rounded text-on-surface-variant hover:bg-surface-variant hover:text-on-surface transition-colors" onClick={() => setZoom(1.0)}>
                    <RotateCcw size={14} />
                  </button>
                </div>
              </div>

              <div className="flex-1 overflow-auto p-4 bg-surface-container-highest/20 relative flex items-center justify-center min-h-[400px]">
                {isLoadingContext && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center bg-surface-container/50 z-10">
                    <RefreshCw size={24} className="animate-spin text-primary mb-2" />
                    <span className="text-sm font-medium text-on-surface-variant">Loading image…</span>
                  </div>
                )}

                {imgSrc ? (
                  <div className="origin-top-left transition-transform duration-200" style={{ transform: `scale(${zoom})` }}>
                    <div className="relative inline-block shadow-2xl rounded overflow-hidden">
                      <img
                        key={imgSrc}
                        src={imgSrc}
                        alt="Document region"
                        className={`max-w-none transition-opacity duration-300 ${imgLoaded ? 'opacity-100' : 'opacity-0'}`}
                        style={{ maxHeight: showFullPage ? 'none' : '400px' }}
                        onLoad={() => { setImgLoaded(true); setImgError(false); }}
                        onError={() => { setImgError(true); setImgLoaded(true); }}
                        draggable={false}
                      />
                      {showFullPage && bbox && imgLoaded && (
                        <div
                          className="absolute border-2 border-primary bg-primary/20 pointer-events-none rounded-sm"
                          style={{
                            left: `${bbox.x * 100}%`,
                            top: `${bbox.y * 100}%`,
                            width: `${bbox.width * 100}%`,
                            height: `${bbox.height * 100}%`,
                          }}
                        />
                      )}
                    </div>
                    {imgError && (
                      <div className="absolute inset-0 flex flex-col items-center justify-center text-amber-500 bg-surface-container/90">
                        <AlertTriangle size={32} className="mb-2" />
                        <span className="text-sm font-medium">Could not load document image.</span>
                      </div>
                    )}
                  </div>
                ) : !isLoadingContext ? (
                  <div className="flex flex-col items-center text-on-surface-variant/50">
                    <FileText size={48} className="mb-2 opacity-50" />
                    <span className="text-sm font-semibold">No image available</span>
                  </div>
                ) : null}
              </div>

              {context && (
                <div className="absolute bottom-4 left-4 right-4 bg-surface-container-high/90 backdrop-blur border border-outline-variant/30 p-3 rounded-lg flex justify-between items-center shadow-lg">
                  <div className="flex items-center gap-3">
                    <span className="px-2 py-1 bg-primary/20 text-primary text-xs font-bold rounded uppercase">Target Field</span>
                    <span className="font-semibold text-on-surface">{context.field_name}</span>
                  </div>
                  {context.document_filename && (
                    <span className="text-sm text-on-surface-variant truncate max-w-[50%]">{context.document_filename}</span>
                  )}
                </div>
              )}
            </div>

            {/* Right: Field Review Panel */}
            <div className="flex flex-col w-full lg:w-[450px] shrink-0">
              {docItems.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full bg-surface-container rounded-2xl border border-outline-variant/20 p-8 text-center">
                  <CheckCircle2 size={48} className="text-emerald-500 mb-4" />
                  <p className="text-xl font-semibold text-on-surface mb-2">Document Complete!</p>
                  <p className="text-on-surface-variant">All fields in this document are reviewed.</p>
                </div>
              ) : (
                <ReviewFieldCard
                  item={context || currentItem}
                  index={currentIndex}
                  total={docItems.length}
                  onAccept={handleAccept}
                  onReject={handleReject}
                  onPrev={handlePrev}
                  onNext={handleNext}
                  isSubmitting={isSubmitting}
                />
              )}
            </div>
          </div>
        </div>
      )}

      {/* Toast Notification */}
      {toastMsg && (
        <div className={`fixed bottom-6 right-6 px-6 py-3 rounded-xl shadow-2xl text-sm font-bold flex items-center gap-2 z-50 animate-fade-in-up border ${
          toastMsg.type === 'error' ? 'bg-error-container text-error border-error/30' : 
          toastMsg.type === 'warn' ? 'bg-amber-500/20 text-amber-500 border-amber-500/30' : 
          'bg-emerald-500/20 text-emerald-500 border-emerald-500/30'
        }`}>
          {toastMsg.msg}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  Clock,
  FileText,
  ExternalLink,
  Calendar,
  RefreshCw,
  AlertTriangle,

  Activity,

  Pill,

  Microscope,
  ShieldAlert,
  MessageCircleQuestion,
  CheckCircle2,
  ClipboardList,
} from 'lucide-react';
import { 
  fetchTimeline, 
  getDocumentFileUrl, 
  fetchPatient,
  fetchPatientRecords,
  fetchContextPanel,
} from '../api';
import ClinicalContextPanel from '../components/ClinicalContextPanel';
import AddNote from '../components/AddNote';
import { useParams, useNavigate } from 'react-router-dom';

import { getEventConfig } from '../utils/timelineEventConfig';
import PatientHeaderBanner from '../components/PatientHeaderBanner';

export default function TimelinePage() {
  const { patientId } = useParams();
  const navigate = useNavigate();

  const [patient, setPatient] = useState(null);
  const [allergies, setAllergies] = useState([]);
  const [events, setEvents] = useState([]);
  const [totalEvents, setTotalEvents] = useState(0);

  const [diagnoses, setDiagnoses] = useState([]);
  const [medications, setMedications] = useState([]);
  const [labResults, setLabResults] = useState([]);
  const [documents, setDocuments] = useState([]);

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [authError, setAuthError] = useState(false);
  const [lastRefreshed, setLastRefreshed] = useState(null);

  const [contextPanel, setContextPanel] = useState(null);
  const [contextPanelLoading, setContextPanelLoading] = useState(true);
  const [contextPanelError, setContextPanelError] = useState(null);

  const [showNoteEntry, setShowNoteEntry] = useState(false);

  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const loadData = useCallback(async (isPolling = false) => {
    if (!patientId) {
      setError("No Patient ID provided in route.");
      setLoading(false);
      return;
    }

    if (!isPolling) setLoading(true);
    else setRefreshing(true);

    setError(null);
    setAuthError(false);

    try {
      // 1. Fetch Patient Info & Timeline in parallel
      const [patientRes, timelineRes] = await Promise.all([
        fetchPatient(patientId),
        fetchTimeline(patientId)
      ]);

      setPatient(patientRes);
      setEvents(timelineRes.events || []);
      setTotalEvents(timelineRes.total_events || 0);
      setLastRefreshed(new Date());

      // 2. Fetch canonical records for clinical summary
      try {
        const recordsRes = await fetchPatientRecords(patientId);
        if (recordsRes) {
          setDiagnoses(recordsRes.diagnoses || []);
          setMedications(recordsRes.medications || []);
          setLabResults(recordsRes.lab_results || []);
          setDocuments(recordsRes.documents || []);
          setAllergies(recordsRes.allergies || []);
        }
      } catch (err) {
        console.warn("Could not load canonical records", err);
      }

      // Story 10.1 — load proactive context panel
      try {
        setContextPanelLoading(true);
        const cpRes = await fetchContextPanel(patientId);
        setContextPanel(cpRes);
        setContextPanelError(null);
      } catch (cpErr) {
        console.warn('Could not load context panel', cpErr);
        setContextPanelError('Could not load context panel.');
      } finally {
        setContextPanelLoading(false);
      }

    } catch (err) {
      console.error('Failed to load patient data:', err);
      if (err.response && err.response.status === 403) {
         setAuthError(true);
         setError("You do not have access to this patient's records.");
      } else {
         setError(err.response?.data?.detail || 'Failed to load timeline events. Please check the backend connection.');
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [patientId]);

  useEffect(() => {
    loadData(false);
  }, [loadData]);

  // Auto-refresh every 15 seconds
  useEffect(() => {
    if (authError || !patientId) return;
    const interval = setInterval(() => {
      loadData(true);
    }, 15000);
    return () => clearInterval(interval);
  }, [loadData, authError, patientId]);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh] text-on-surface-variant">
        <RefreshCw size={32} className="animate-spin mb-4 text-primary" />
        <p>Loading patient timeline…</p>
      </div>
    );
  }

  if (authError) {
    return (
      <div className="p-6 md:p-8 max-w-[1200px] mx-auto">
        <div className="flex flex-col items-center justify-center min-h-[40vh] bg-error-container/20 border border-error/30 rounded-2xl p-8 text-center">
          <ShieldAlert size={64} className="text-error mb-4" />
          <h2 className="text-headline-sm font-headline-sm text-error mb-2">Access Denied</h2>
          <p className="text-on-surface-variant">You do not have authorization to view the records for Patient ID: <strong>{patientId}</strong></p>
          <button className="mt-6 px-6 py-2 bg-surface-variant text-on-surface rounded-lg font-semibold hover:bg-surface-variant/80 transition-colors" onClick={() => navigate('/patients')}>
            Return to Patients List
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="app-container flex flex-col gap-6">

      {/* ── Patient Header Banner ── */}
      <PatientHeaderBanner patient={patient} allergies={allergies} />

      {error && (
        <div className="p-4 bg-error-container/20 text-error border border-error/30 rounded-xl flex items-center gap-3">
          <AlertTriangle size={20} />
          <span className="font-medium text-sm">{error}</span>
        </div>
      )}

      {/* ── Clinical Summary Grid ── */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-2">
        <div className="bg-surface-container rounded-xl border border-outline-variant/30 p-4 shadow-sm flex flex-col h-64">
          <h3 className="flex items-center gap-2 text-on-surface font-semibold mb-3 border-b border-outline-variant/20 pb-2">
            <Activity size={16} className="text-amber-500" /> Diagnoses
          </h3>
          <div className="overflow-y-auto flex-1 pr-1 custom-scrollbar">
            {diagnoses.length > 0 ? (
              <ul className="flex flex-col gap-2">
                {diagnoses.map(d => (
                  <li key={d.id} className="bg-surface-container-high rounded-lg p-2 text-sm">
                    <div className="text-on-surface font-medium">{d.raw_text}</div>
                    {d.icd10_code && <div className="mt-1 font-mono text-[10px] text-slate-500">ICD-10: {d.icd10_code}</div>}
                    {d.snomed_code && <div className="mt-1 font-mono text-[10px] text-slate-500">SNOMED: {d.snomed_code}</div>}
                  </li>
                ))}
              </ul>
            ) : <p className="text-sm text-on-surface-variant/70 italic text-center mt-4">No diagnoses recorded.</p>}
          </div>
        </div>

        <div className="bg-surface-container rounded-xl border border-outline-variant/30 p-4 shadow-sm flex flex-col h-64">
          <h3 className="flex items-center gap-2 text-on-surface font-semibold mb-3 border-b border-outline-variant/20 pb-2">
            <Pill size={16} className="text-emerald-500" /> Medications
          </h3>
          <div className="overflow-y-auto flex-1 pr-1 custom-scrollbar">
            {medications.length > 0 ? (
              <ul className="flex flex-col gap-2">
                {medications.map(m => (
                  <li key={m.id} className="bg-surface-container-high rounded-lg p-2 text-sm">
                    <div className="text-on-surface font-medium">{m.raw_text}</div>
                    {m.rxnorm_code && <div className="mt-1 font-mono text-[10px] text-slate-500">RxNorm: {m.rxnorm_code}</div>}
                  </li>
                ))}
              </ul>
            ) : <p className="text-sm text-on-surface-variant/70 italic text-center mt-4">No medications recorded.</p>}
          </div>
        </div>

        <div className="bg-surface-container rounded-xl border border-outline-variant/30 p-4 shadow-sm flex flex-col h-64">
          <h3 className="flex items-center gap-2 text-on-surface font-semibold mb-3 border-b border-outline-variant/20 pb-2">
            <Microscope size={16} className="text-violet-500" /> Lab Results
          </h3>
          <div className="overflow-y-auto flex-1 pr-1 custom-scrollbar">
            {labResults.length > 0 ? (
              <ul className="flex flex-col gap-2">
                {labResults.map(l => (
                  <li key={l.id} className="bg-surface-container-high rounded-lg p-2 text-sm">
                    <div className="text-on-surface font-medium">{l.raw_text}</div>
                    {l.loinc_code && <div className="mt-1 font-mono text-[10px] text-slate-500">LOINC: {l.loinc_code}</div>}
                  </li>
                ))}
              </ul>
            ) : <p className="text-sm text-on-surface-variant/70 italic text-center mt-4">No lab results recorded.</p>}
          </div>
        </div>

        <div className="bg-surface-container rounded-xl border border-outline-variant/30 p-4 shadow-sm flex flex-col h-64">
          <h3 className="flex items-center gap-2 text-on-surface font-semibold mb-3 border-b border-outline-variant/20 pb-2">
            <FileText size={16} className="text-primary" /> Documents
          </h3>
          <div className="overflow-y-auto flex-1 pr-1 custom-scrollbar">
            {documents.length > 0 ? (
              <ul className="flex flex-col gap-2">
                {documents.map(d => (
                  <li key={d.document_id} className="bg-surface-container-high rounded-lg p-2 text-sm flex flex-col gap-1">
                    <div className="text-on-surface font-medium truncate" title={d.filename}>{d.filename}</div>
                    <div className="text-xs text-on-surface-variant">{d.document_type || 'Unknown Type'}</div>
                  </li>
                ))}
              </ul>
            ) : <p className="text-sm text-on-surface-variant/70 italic text-center mt-4">No documents recorded.</p>}
          </div>
        </div>
      </div>

      {/* ── Header Controls ── */}
      <header className="app-header">
        <div className="brand-wrapper">
          <div className="brand-logo" style={{ background: 'linear-gradient(135deg, var(--accent-emerald), var(--primary-cyan))' }}>
            <Clock size={26} color="#ffffff" />
          </div>
          <div className="brand-title">
            <h2>Longitudinal Timeline</h2>
            <p>Chronological sequence of verified clinical events</p>
          </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          {lastRefreshed && (
            <span className="text-xs font-medium text-on-surface-variant hidden sm:inline-block">
              Updated {lastRefreshed.toLocaleTimeString()}
            </span>
          )}

          <button
            className="flex items-center gap-2 px-3 py-1.5 bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 rounded-lg font-semibold hover:bg-emerald-500/20 transition-colors text-sm"
            onClick={() => setShowNoteEntry(true)}
            data-testid="open-note-entry-btn"
          >
            <ClipboardList size={14} />
            Add Note
          </button>

          <button
            className="flex items-center gap-2 px-3 py-1.5 bg-primary/10 text-primary border border-primary/20 rounded-lg font-semibold hover:bg-primary/20 transition-colors text-sm"
            onClick={() => navigate(`/patients/${patientId}/ask`)}
          >
            <MessageCircleQuestion size={14} />
            Ask QA
          </button>

          <button
            className="flex items-center gap-2 px-3 py-1.5 bg-surface-variant text-on-surface rounded-lg font-semibold hover:bg-surface-variant/80 transition-colors text-sm"
            onClick={() => loadData(false)}
            disabled={refreshing}
          >
            <RefreshCw size={14} className={refreshing ? 'animate-spin' : ''} />
            Refresh
          </button>
        </div>
      </header>

      {/* ── Timeline Track ── */}
      <div className="relative pt-4 pb-8 pl-4 sm:pl-8">

        {/* The Stem */}
        <div className="absolute top-4 bottom-8 left-[23px] sm:left-[39px] w-[2px] bg-gradient-to-b from-primary via-primary/50 to-transparent"></div>

        {events.length === 0 ? (
          <div className="ml-8 sm:ml-12 p-8 bg-surface-container rounded-2xl border border-outline-variant/20 text-center flex flex-col items-center justify-center min-h-[250px]">
            <Clock size={40} className="text-on-surface-variant/50 mb-3" />
            <h3 className="text-lg font-semibold text-on-surface mb-1">No events recorded</h3>
            <p className="text-on-surface-variant text-sm">Once documents for this patient pass review and are committed, they will appear here chronologically.</p>
          </div>
        ) : (
          <div className="flex flex-col gap-6">
            {events.slice((currentPage - 1) * pageSize, currentPage * pageSize).map((event, index) => {
              const cfg = getEventConfig(event.event_type || event.field_name);
              const fileUrl = getDocumentFileUrl(event.document_id);

              return (
                <div key={event.event_id || index} className="relative ml-8 sm:ml-12 group">

                  {/* Node Dot */}
                  <div className={`absolute -left-[37px] sm:-left-[53px] top-5 w-4 h-4 rounded-full ${cfg.bg} border-[3px] border-surface shadow-[0_0_10px_rgba(0,0,0,0.2)] z-10 transition-transform duration-300 group-hover:scale-125`} style={{ boxShadow: `0 0 12px var(--color-${cfg.bg.split('-')[1]})` }}></div>

                  {/* Event Card */}
                  <div className={`bg-surface-container rounded-2xl border ${cfg.border} p-5 hover:bg-surface-container-high transition-colors shadow-sm`}>

                    {/* Card Header */}
                    <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4 mb-3">

                      <div className="flex flex-wrap items-center gap-3">
                        <div className={`flex items-center gap-1.5 px-3 py-1.5 ${cfg.containerBg} ${cfg.color} ${cfg.border} border rounded-lg text-sm font-bold shadow-sm`}>
                          {cfg.icon}
                          <span className="capitalize">{cfg.label}</span>
                        </div>

                        <div className="flex items-center gap-1.5 text-sm font-semibold text-on-surface-variant bg-surface-variant px-3 py-1.5 rounded-lg border border-outline-variant/20">
                          <Calendar size={14} />
                          {event.event_date || 'Unknown Date'}
                        </div>
                      </div>

                      {fileUrl && (
                        <a
                          href={fileUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center gap-1.5 px-3 py-1.5 bg-primary/10 hover:bg-primary/20 text-primary rounded-lg font-semibold text-sm transition-colors shrink-0 border border-primary/20"
                        >
                          <ExternalLink size={14} /> View Source
                        </a>
                      )}
                    </div>

                    {/* Summary / Value */}
                    <div className="text-base font-semibold text-on-surface mb-4 pl-1">
                      {event.summary || event.value || event.raw_text || 'Event recorded'}
                    </div>

                    {/* Footer Metadata */}
                    <div className="flex flex-wrap items-center gap-x-6 gap-y-2 pt-3 border-t border-outline-variant/10 text-xs font-medium text-on-surface-variant pl-1">
                      {event.filename && (
                        <div className="flex items-center gap-1.5">
                          <FileText size={14} className="opacity-70" />
                          <span>Extracted from: <strong className="text-on-surface">{event.filename}</strong></span>
                        </div>
                      )}

                      {event.verification_status && (
                        <div className="flex items-center gap-1.5 text-emerald-500">
                          <CheckCircle2 size={14} />
                          <span className="capitalize">{event.verification_status.replace('_', ' ')}</span>
                        </div>
                      )}

                      {event.confidence_score !== undefined && (
                        <div className="flex items-center gap-1.5">
                          <span className="opacity-70">Confidence:</span>
                          <strong className={event.confidence_score >= 0.8 ? 'text-emerald-500' : 'text-amber-500'}>
                            {Math.round(event.confidence_score * 100)}%
                          </strong>
                        </div>
                      )}
                    </div>

                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Pagination Controls */}
      {!loading && events.length > 0 && (
        <div className="flex items-center justify-between mt-4 mb-8 text-sm pl-4 sm:pl-8">
          <div className="text-on-surface-variant ml-8 sm:ml-12">
            Showing {((currentPage - 1) * pageSize) + 1} to {Math.min(currentPage * pageSize, events.length)} of {events.length} events
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="px-3 py-1.5 rounded-lg border border-outline-variant/30 bg-surface-container hover:bg-surface-variant disabled:opacity-50 transition-colors"
            >
              Previous
            </button>
            <span className="px-3 py-1.5 font-medium">Page {currentPage} of {Math.ceil(events.length / pageSize) || 1}</span>
            <button
              onClick={() => setCurrentPage(p => Math.min(Math.ceil(events.length / pageSize), p + 1))}
              disabled={currentPage === (Math.ceil(events.length / pageSize) || 1)}
              className="px-3 py-1.5 rounded-lg border border-outline-variant/30 bg-surface-container hover:bg-surface-variant disabled:opacity-50 transition-colors"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* ── Story 10.1: Note-Entry Screen with Clinical Context Panel ── */}
      {showNoteEntry && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4"
          data-testid="note-entry-overlay"
        >
          <div className="w-full max-w-5xl max-h-[90vh] overflow-y-auto bg-surface rounded-2xl border border-outline-variant/30 shadow-2xl flex flex-col">

            {/* Overlay Header */}
            <div className="flex items-center justify-between p-5 border-b border-outline-variant/20">
              <div className="flex items-center gap-3">
                <ClipboardList size={20} className="text-primary" />
                <div>
                  <h2 className="text-base font-bold text-on-surface">New Clinical Note</h2>
                  <p className="text-xs text-on-surface-variant">
                    {patient?.name ?? 'Patient'} — {patient?.mrn ?? patientId}
                  </p>
                </div>
              </div>
              <button
                onClick={() => setShowNoteEntry(false)}
                className="p-2 rounded-lg hover:bg-surface-variant transition-colors text-on-surface-variant"
                aria-label="Close note entry"
                data-testid="close-note-entry-btn"
              >
                ✕
              </button>
            </div>

            {/* Two-column body: note area (left) + context panel (right) */}
            <div className="flex flex-col md:flex-row gap-0 flex-1 overflow-hidden">

              {/* Note Text Area */}
              <div className="flex-1 p-5 overflow-y-auto">
                <AddNote patientId={patientId} />
              </div>


              {/* Context Panel */}
              <div
                className="md:w-80 shrink-0 border-t md:border-t-0 md:border-l border-outline-variant/20 p-5 overflow-y-auto"
                data-testid="context-panel-column"
              >
                <ClinicalContextPanel
                  panel={contextPanel}
                  loading={contextPanelLoading}
                  error={contextPanelError}
                />
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { 

  FileCheck, 
  Clock, 
  Layers, 
  RefreshCw, 
  Search, 
  Database,
  ExternalLink,
  ShieldCheck,
  Trash2,
  AlertOctagon,
  ListFilter,
  Code,
  Filter,
  Loader2
} from 'lucide-react';
import FileUploader from '../components/FileUploader';
import ExtractedFieldsModal from '../components/ExtractedFieldsModal';
import { fetchDocuments, fetchDocumentStatus, deleteDocument, deleteAllDocuments, fetchUploadLogs, getWatchedFolderConfig, updateWatchedFolderConfig, fetchHealth, API_BASE_URL } from '../api';

export default function UploadPage() {
  const navigate = useNavigate();
  const [documents, setDocuments] = useState([]);
  const [uploadLogs, setUploadLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('documents'); // 'documents' or 'logs'
  const [searchQuery, setSearchQuery] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [selectedDocForFields, setSelectedDocForFields] = useState(null);

  // Filters
  const [filterNeedsReview, setFilterNeedsReview] = useState(false);
  const [filterDocType, setFilterDocType] = useState('');

  const { user } = useAuth();
  const [watchFolderPath, setWatchFolderPath] = useState('');
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [toastMsg, setToastMsg] = useState(null);
  const [pipelineActive, setPipelineActive] = useState(true);

  // Pagination states
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 15;

  const refreshInFlight = useRef(false);

  const loadData = async () => {
    if (refreshInFlight.current) return;
    refreshInFlight.current = true;
    setIsRefreshing(true);
    try {
      const needsReviewParam = filterNeedsReview ? true : null;
      const docTypeParam = filterDocType || null;

      try {
        const docsData = await fetchDocuments(needsReviewParam, docTypeParam);
        setDocuments(docsData);
      } catch (err) {
        console.error('Failed to load documents:', err);
      }

      try {
        const logsData = await fetchUploadLogs();
        setUploadLogs(logsData);
      } catch (err) {
        console.error('Failed to load upload logs:', err);
      }
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
      refreshInFlight.current = false;
    }
  };

  const loadConfig = async () => {
    if (user && user.role && user.role.toLowerCase() === 'hospital_admin') {
      try {
        const config = await getWatchedFolderConfig();
        setWatchFolderPath(config.path);
      } catch (err) {
        console.error('Failed to load watched folder config', err);
      }
    }
  };

  const checkHealth = async () => {
    try {
      await fetchHealth();
      setPipelineActive(true);
    } catch (err) {
      setPipelineActive(false);
    }
  };

  useEffect(() => {
    loadData();
    loadConfig();
    checkHealth();

    // Poll health every 15 seconds
    const healthInterval = setInterval(checkHealth, 15000);
    return () => clearInterval(healthInterval);
  }, [filterNeedsReview, filterDocType, user]); // Re-fetch when filters change

  const pollingRef = useRef({});

  useEffect(() => {
    const TERMINAL = new Set(['extracted', 'failed', 'verified', 'committed', 'unlinked', 'rejected', 'pending_review']);
    const MIN_DELAY = 2000;
    const MAX_DELAY = 15000;
    const BACKOFF_FACTOR = 1.5;

    const activeDocs = documents.filter(
      (doc) => !TERMINAL.has((doc.status || '').toLowerCase())
    );

    const activeIds = new Set(activeDocs.map((d) => d.document_id));
    for (const [docId, entry] of Object.entries(pollingRef.current)) {
      if (!activeIds.has(docId)) {
        clearTimeout(entry.timeoutId);
        delete pollingRef.current[docId];
      }
    }

    for (const doc of activeDocs) {
      if (pollingRef.current[doc.document_id]) continue;

      const scheduleNext = (docId, delay) => {
        const timeoutId = setTimeout(async () => {
          if (document.visibilityState !== 'visible') {
            pollingRef.current[docId] = { timeoutId: null, delay };
            scheduleNext(docId, delay);
            return;
          }
          try {
            const statusData = await fetchDocumentStatus(docId);
            setDocuments((current) =>
              current.map((item) =>
                item.document_id === docId ? { ...item, ...statusData } : item
              )
            );
            if (TERMINAL.has((statusData.status || '').toLowerCase())) {
              delete pollingRef.current[docId];
              return;
            }
          } catch (err) {
            console.error(`Failed to poll status for ${docId}:`, err);
          }
          const nextDelay = Math.min(delay * BACKOFF_FACTOR, MAX_DELAY);
          pollingRef.current[docId] = { timeoutId: null, delay: nextDelay };
          scheduleNext(docId, nextDelay);
        }, delay);
        pollingRef.current[docId] = { timeoutId, delay };
      };

      scheduleNext(doc.document_id, MIN_DELAY);
    }

    return () => {
      for (const entry of Object.values(pollingRef.current)) {
        clearTimeout(entry.timeoutId);
      }
      pollingRef.current = {};
    };
  }, [documents.length]);

  const statusLabel = (status) => ({
    queued: 'Queued',
    new: 'Queued',
    preprocessing: 'Preprocessing...',
    preprocessed: 'Detecting layout...',
    detecting_layout: 'Detecting layout...',
    layout_detected: 'Classifying...',
    classifying: 'Classifying...',
    classified: 'Extracting text...',
    extracting: 'Extracting text...',
    extracted: 'Extracted',
    failed: 'Failed',
    verified: 'Verified',
    committed: 'Committed',
    unlinked: 'Unlinked',
    rejected: 'Rejected',
    pending_review: 'Pending Review'
  }[(status || '').toLowerCase()] || status || 'Queued');

  const getStatusBadgeClass = (status) => {
    const s = (status || '').toUpperCase();
    if (s === 'QUEUED') return 'bg-amber-500/15 text-amber-500 border-amber-500/30';
    if (s === 'FAILED') return 'bg-error-container/15 text-error border-error/30';
    if (s === 'EXTRACTED' || s === 'VERIFIED') return 'bg-emerald-500/15 text-emerald-500 border-emerald-500/30';
    return 'bg-primary/15 text-primary border-primary/30';
  };

  const handleUploadSuccess = () => {
    loadData();
  };

  const handleDeleteDocument = async (e, documentId, filename) => {
    e.stopPropagation(); // Prevent row click
    if (!window.confirm(`Delete document "${filename}"?`)) return;
    try {
      await deleteDocument(documentId);
      await loadData();
    } catch (err) {
      console.error('Failed to delete document:', err);
    }
  };

  const handleDeleteAll = async () => {
    if (!window.confirm(`Delete ALL ${documents.length} document(s)? This cannot be undone.`)) return;
    try {
      await deleteAllDocuments();
      await loadData();
    } catch (err) {
      console.error('Failed to delete all documents:', err);
    }
  };

  const handleRowClick = (doc) => {
    navigate(`/review?documentId=${doc.document_id}`);
  };

  const handleSaveConfig = async () => {
    setIsSavingConfig(true);
    setToastMsg(null);
    try {
      const result = await updateWatchedFolderConfig(watchFolderPath);
      setWatchFolderPath(result.path);
      setToastMsg({ type: 'success', msg: 'Watched folder path updated successfully.' });
      setTimeout(() => setToastMsg(null), 3000);
    } catch (err) {
      setToastMsg({ type: 'error', msg: err.response?.data?.detail || 'Failed to update watched folder path.' });
      setTimeout(() => setToastMsg(null), 5000);
    } finally {
      setIsSavingConfig(false);
    }
  };

  const filteredDocuments = documents.filter((doc) => {
    const q = searchQuery.toLowerCase();
    return (
      doc.filename.toLowerCase().includes(q) ||
      doc.document_id.toLowerCase().includes(q) ||
      doc.filetype.toLowerCase().includes(q)
    );
  });

  const filteredLogs = uploadLogs.filter((log) => {
    const q = searchQuery.toLowerCase();
    return (
      log.filename.toLowerCase().includes(q) ||
      (log.reason && log.reason.toLowerCase().includes(q)) ||
      log.status.toLowerCase().includes(q)
    );
  });

  // Calculate paginated slices
  const totalPages = Math.ceil(filteredDocuments.length / pageSize);
  const paginatedDocuments = filteredDocuments.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  );

  const totalLogPages = Math.ceil(filteredLogs.length / pageSize);
  const paginatedLogs = filteredLogs.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  );

  // Reset page to 1 when filters or tabs change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, filterNeedsReview, filterDocType, activeTab]);

  const queuedCount = documents.filter((d) => d.status === 'QUEUED' || d.status === 'new').length;
  const rejectedLogsCount = uploadLogs.filter((l) => l.status === 'REJECTED').length;
  const acceptedLogsCount = uploadLogs.filter((l) => l.status === 'ACCEPTED').length;

  const formatDate = (isoString) => {
    if (!isoString) return 'N/A';
    const dt = new Date(isoString);
    return dt.toLocaleString(undefined, {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  };

  return (
    <div className="app-container">
      {/* Header Section */}
      <header className="app-header">
        <div className="brand-wrapper">
          <div className="brand-logo" style={{ background: 'linear-gradient(135deg, var(--accent-emerald), var(--primary-cyan))' }}>
            <FileCheck size={26} color="#ffffff" />
          </div>
          <div className="brand-title">
            <h1>Document Intake Queue</h1>
            <p>Monitor and manage the document processing pipeline</p>
          </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          {pipelineActive ? (
            <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-primary/10 border border-primary/20">
              <div className="w-2 h-2 rounded-full bg-primary animate-pulse shadow-[0_0_8px_rgba(6,182,212,0.6)]"></div>
              <span className="text-sm font-semibold text-primary">Pipeline Active</span>
            </div>
          ) : (
            <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-error-container/20 border border-error/30">
              <div className="w-2 h-2 rounded-full bg-error shadow-[0_0_8px_rgba(239,68,68,0.6)]"></div>
              <span className="text-sm font-semibold text-error">Pipeline Offline</span>
            </div>
          )}
          <a
            href={`${API_BASE_URL.replace('/api/v1', '')}/docs`}
            target="_blank"
            rel="noopener noreferrer"
            className="btn btn-secondary" style={{ padding: '0.5rem 1rem' }}
          >
            API Docs <ExternalLink size={16} />
          </a>
        </div>
      </header>

      {/* Overview Stat Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <div className="p-6 rounded-2xl bg-surface-container border border-outline-variant/20 hover:border-outline-variant/40 transition-colors">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-body-md font-body-md text-on-surface-variant">Total Documents</h3>
            <div className="p-2 rounded-lg bg-secondary-container/20 text-secondary">
              <Layers size={20} />
            </div>
          </div>
          <div className="text-headline-display font-headline-display text-on-surface">{documents.length}</div>
        </div>

        <div className="p-6 rounded-2xl bg-surface-container border border-outline-variant/20 hover:border-outline-variant/40 transition-colors">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-body-md font-body-md text-on-surface-variant">Status: QUEUED</h3>
            <div className="p-2 rounded-lg bg-amber-500/10 text-amber-500">
              <Clock size={20} />
            </div>
          </div>
          <div className="text-headline-display font-headline-display text-on-surface">{queuedCount}</div>
        </div>

        <div className="p-6 rounded-2xl bg-surface-container border border-outline-variant/20 hover:border-outline-variant/40 transition-colors">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-body-md font-body-md text-on-surface-variant">Rejected Uploads</h3>
            <div className="p-2 rounded-lg bg-error-container/10 text-error">
              <AlertOctagon size={20} />
            </div>
          </div>
          <div className="text-headline-display font-headline-display text-error">{rejectedLogsCount}</div>
        </div>

        <div className="p-6 rounded-2xl bg-surface-container border border-outline-variant/20 hover:border-outline-variant/40 transition-colors">
          <div className="flex justify-between items-start mb-4">
            <h3 className="text-body-md font-body-md text-on-surface-variant">Validated Initial</h3>
            <div className="p-2 rounded-lg bg-emerald-500/10 text-emerald-500">
              <ShieldCheck size={20} />
            </div>
          </div>
          <div className="text-headline-display font-headline-display text-on-surface">100%</div>
        </div>
      </div>

      {/* Settings Card for Hospital Admin */}
      {user && user.role && user.role.toLowerCase() === 'hospital_admin' && (
        <div className="bg-surface-container rounded-xl border border-outline-variant/20 p-6 mb-8">
          <div className="flex items-center gap-2 mb-2">
            <Database size={20} className="text-primary" />
            <h3 className="text-lg font-semibold text-on-surface">Scanner Watch Folder</h3>
          </div>
          <p className="text-sm text-on-surface-variant mb-4">
            Specify an absolute folder path on the server where the backend is running.
            The system will automatically monitor this directory and ingest newly scanned files.
          </p>
          <div className="flex items-center gap-4">
            <input
              type="text"
              value={watchFolderPath}
              onChange={(e) => setWatchFolderPath(e.target.value)}
              placeholder="/var/lib/scanner_intake"
              className="flex-1 bg-surface-container-high border border-outline-variant/30 text-on-surface text-sm rounded-lg px-4 py-2 focus:outline-none focus:border-primary"
            />
            <button
              onClick={handleSaveConfig}
              disabled={isSavingConfig || !watchFolderPath.trim()}
              className="btn btn-primary"
            >
              {isSavingConfig ? 'Saving...' : 'Save Path'}
            </button>
          </div>
        </div>
      )}

      {/* File Uploader Section */}
      <FileUploader onUploadSuccess={handleUploadSuccess} />

      {/* Filters and Search */}
      <div className="flex flex-col md:flex-row justify-between gap-4 mb-6">
        <div className="flex items-center gap-4">
          <button
            onClick={() => setActiveTab('documents')}
            className={`px-4 py-2 rounded-lg font-semibold text-sm transition-colors ${
              activeTab === 'documents' ? 'bg-primary text-on-primary' : 'text-on-surface-variant hover:bg-surface-variant'
            }`}
          >
            Queued Documents ({documents.length})
          </button>
          <button
            onClick={() => setActiveTab('logs')}
            className={`px-4 py-2 rounded-lg font-semibold text-sm transition-colors ${
              activeTab === 'logs' ? 'bg-primary text-on-primary' : 'text-on-surface-variant hover:bg-surface-variant'
            }`}
          >
            Upload Audit Logs ({uploadLogs.length})
          </button>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          {activeTab === 'documents' && (
            <>
              {/* Needs Review Filter */}
              <label className="flex items-center gap-2 cursor-pointer">
                <div className="relative">
                  <input type="checkbox" className="sr-only" checked={filterNeedsReview} onChange={(e) => setFilterNeedsReview(e.target.checked)} />
                  <div className={`block w-10 h-6 rounded-full transition-colors ${filterNeedsReview ? 'bg-primary' : 'bg-surface-variant'}`}></div>
                  <div className={`dot absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform ${filterNeedsReview ? 'transform translate-x-4' : ''}`}></div>
                </div>
                <span className="text-sm font-semibold text-on-surface-variant">Needs Review</span>
              </label>

              {/* Doc Type Dropdown */}
              <div className="relative">
                <select
                  className="appearance-none bg-surface-container border border-outline-variant/30 text-on-surface text-sm rounded-lg pl-3 pr-8 py-2 focus:outline-none focus:border-primary"
                  value={filterDocType}
                  onChange={(e) => setFilterDocType(e.target.value)}
                >
                  <option value="">All Document Types</option>
                  <option value="Prescription">Prescription</option>
                  <option value="Lab Report">Lab Report</option>
                  <option value="Discharge Summary">Discharge Summary</option>
                  <option value="Referral">Referral</option>
                  <option value="Admission Form">Admission Form</option>
                  <option value="Unknown">Unknown</option>
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-on-surface-variant">
                  <Filter size={14} />
                </div>
              </div>
            </>
          )}

          <div className="relative w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-on-surface-variant w-4 h-4" />
            <input
              type="text"
              placeholder="Search..."
              className="w-full bg-surface-container border border-outline-variant/30 text-on-surface text-sm rounded-lg pl-9 pr-3 py-2 focus:outline-none focus:border-primary placeholder-on-surface-variant/50"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          <button
            onClick={loadData}
            disabled={isRefreshing}
            className="p-2 rounded-lg bg-surface-variant border border-outline-variant/30 text-on-surface hover:bg-surface-variant/80 transition-colors disabled:opacity-50"
          >
            <RefreshCw size={18} className={isRefreshing ? 'animate-spin' : ''} />
          </button>

          {documents.length > 0 && (
            <button
              onClick={handleDeleteAll}
              className="p-2 rounded-lg bg-error-container/10 border border-error/30 text-error hover:bg-error-container/20 transition-colors"
              title="Delete All Documents"
            >
              <Trash2 size={18} />
            </button>
          )}
        </div>
      </div>

      {/* Table Area */}
      <div className="bg-surface-container rounded-xl border border-outline-variant/20 overflow-hidden">
        {isLoading ? (
          <div className="p-12 text-center text-on-surface-variant">
            <Loader2 size={32} className="animate-spin mx-auto mb-4 text-primary" />
            <p>Loading database repository...</p>
          </div>
        ) : activeTab === 'documents' ? (
          filteredDocuments.length === 0 ? (
            <div className="p-16 text-center text-on-surface-variant">
              <Database size={48} className="mx-auto mb-4 opacity-50" />
              <p className="text-lg font-semibold text-on-surface mb-2">No documents found.</p>
              <p className="text-sm">Upload files above or adjust your search/filters.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-surface-container-high border-b border-outline-variant/20 text-on-surface-variant font-label-caps text-xs uppercase tracking-wider">
                  <tr>
                    <th className="px-6 py-4 font-semibold">Filename</th>
                    <th className="px-6 py-4 font-semibold">Format</th>
                    <th className="px-6 py-4 font-semibold">Ingestion Date</th>
                    <th className="px-6 py-4 font-semibold">Status</th>
                    <th className="px-6 py-4 font-semibold">Document Type</th>
                    <th className="px-6 py-4 font-semibold">Confidence</th>
                    <th className="px-6 py-4 font-semibold">Review</th>
                    <th className="px-6 py-4 font-semibold">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-outline-variant/10">
                  {paginatedDocuments.map((doc) => (
                    <tr 
                      key={doc.document_id} 
                      className="hover:bg-surface-variant/30 transition-colors cursor-pointer"
                      onClick={() => handleRowClick(doc)}
                    >
                      <td className="px-6 py-4 font-semibold text-on-surface">
                        <div className="max-w-[200px] truncate" title={doc.filename}>{doc.filename}</div>
                        <div className="text-[10px] text-primary font-data-tabular mt-1">{doc.document_id.substring(0, 13)}...</div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="px-2 py-1 rounded bg-surface-variant text-[10px] font-bold text-on-surface-variant uppercase border border-outline-variant/20">
                          {doc.filetype}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-on-surface-variant text-xs">
                        {formatDate(doc.uploaded_at)}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase border ${getStatusBadgeClass(doc.status)}`}>
                          <span className="w-1.5 h-1.5 rounded-full bg-current animate-pulse"></span>
                          {statusLabel(doc.status)}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-on-surface-variant">
                        {doc.document_type || '-'}
                      </td>
                      <td className="px-6 py-4 font-data-tabular">
                        {doc.extraction_confidence != null ? (
                          <div className="flex items-center gap-1.5 cursor-help" title="Overall Extraction Confidence">
                            <span className="text-primary font-medium">{doc.extraction_confidence.toFixed(2)}</span>
                            <Database size={12} className="text-primary/70" />
                          </div>
                        ) : doc.classification_confidence != null ? (
                          <div className="flex items-center gap-1.5 cursor-help text-on-surface-variant/70" title="Classification Confidence">
                            <span>{doc.classification_confidence.toFixed(2)}</span>
                            <Layers size={12} />
                          </div>
                        ) : (
                          <span className="text-on-surface-variant">-</span>
                        )}
                      </td>
                      <td className="px-6 py-4">
                        {doc.needs_manual_review === true || (doc.status || '').toUpperCase() === 'UNLINKED' ? (
                          <span className="px-2 py-1 rounded bg-error-container/20 text-error text-xs font-bold border border-error/30">Needs Review</span>
                        ) : doc.needs_manual_review === false && ['EXTRACTED', 'VERIFIED', 'COMMITTED'].includes((doc.status || '').toUpperCase()) ? (
                          <span className="text-emerald-500 text-xs font-bold">Verified</span>
                        ) : <span className="text-on-surface-variant">-</span>}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2">
                          <button
                            className="p-1.5 rounded-md text-on-surface-variant hover:text-primary hover:bg-primary/10 transition-colors disabled:opacity-30 disabled:hover:bg-transparent disabled:hover:text-on-surface-variant"
                            onClick={(e) => { e.stopPropagation(); setSelectedDocForFields(doc); }}
                            disabled={!['EXTRACTED', 'PENDING_REVIEW', 'COMMITTED', 'VERIFIED', 'UNLINKED'].includes((doc.status || '').toUpperCase())}
                            title="View extracted JSON"
                          >
                            <Code size={18} />
                          </button>
                          <button
                            className="p-1.5 rounded-md text-on-surface-variant hover:text-error hover:bg-error-container/10 transition-colors"
                            title="Delete document"
                            onClick={(e) => handleDeleteDocument(e, doc.document_id, doc.filename)}
                          >
                            <Trash2 size={18} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )
        ) : (
          /* Upload Logs Table */
          filteredLogs.length === 0 ? (
            <div className="p-16 text-center text-on-surface-variant">
              <ListFilter size={48} className="mx-auto mb-4 opacity-50" />
              <p className="text-lg font-semibold text-on-surface mb-2">No upload log entries recorded yet.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-surface-container-high border-b border-outline-variant/20 text-on-surface-variant font-label-caps text-xs uppercase tracking-wider">
                  <tr>
                    <th className="px-6 py-4 font-semibold">Timestamp</th>
                    <th className="px-6 py-4 font-semibold">Filename</th>
                    <th className="px-6 py-4 font-semibold">Validation Status</th>
                    <th className="px-6 py-4 font-semibold">Rejection Reason</th>
                    <th className="px-6 py-4 font-semibold">Client IP</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-outline-variant/10">
                  {paginatedLogs.map((log) => (
                    <tr key={log.id} className="hover:bg-surface-variant/30 transition-colors">
                      <td className="px-6 py-4 text-on-surface-variant text-xs">
                        {formatDate(log.timestamp)}
                      </td>
                      <td className="px-6 py-4 font-semibold text-on-surface max-w-[250px] truncate" title={log.filename}>
                        {log.filename}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase border ${
                          log.status === 'REJECTED' 
                            ? 'bg-error-container/20 text-error border-error/30' 
                            : 'bg-emerald-500/15 text-emerald-500 border-emerald-500/30'
                        }`}>
                          {log.status === 'REJECTED' ? '❌ REJECTED' : '✓ ACCEPTED'}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <span className={`text-xs ${log.status === 'REJECTED' ? 'text-error/80 font-medium' : 'text-on-surface-variant'}`}>
                          {log.reason || 'None (Validated & Queued)'}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-on-surface-variant text-xs font-data-tabular">
                        {log.client_ip || '127.0.0.1'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )
        )}
      </div>

      {/* Pagination Controls */}
      {!isLoading && (
        <div className="flex items-center justify-between mt-4 mb-8 text-sm">
          <div className="text-on-surface-variant">
            Showing {((currentPage - 1) * pageSize) + 1} to {Math.min(currentPage * pageSize, activeTab === 'documents' ? filteredDocuments.length : filteredLogs.length)} of {activeTab === 'documents' ? filteredDocuments.length : filteredLogs.length} entries
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
              disabled={currentPage === 1}
              className="px-3 py-1.5 rounded-lg border border-outline-variant/30 bg-surface-container hover:bg-surface-variant disabled:opacity-50 transition-colors"
            >
              Previous
            </button>
            <span className="px-3 py-1.5 font-medium">Page {currentPage} of {activeTab === 'documents' ? (totalPages || 1) : (totalLogPages || 1)}</span>
            <button
              onClick={() => setCurrentPage(p => Math.min(activeTab === 'documents' ? totalPages : totalLogPages, p + 1))}
              disabled={currentPage === (activeTab === 'documents' ? (totalPages || 1) : (totalLogPages || 1))}
              className="px-3 py-1.5 rounded-lg border border-outline-variant/30 bg-surface-container hover:bg-surface-variant disabled:opacity-50 transition-colors"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* Extracted Fields Modal */}
      {selectedDocForFields && (
        <ExtractedFieldsModal
          document={selectedDocForFields}
          onClose={() => setSelectedDocForFields(null)}
          onRefreshRequired={loadData}
        />
      )}
      {/* Toast Notification */}
      {toastMsg && (
        <div className="fixed bottom-6 right-6 z-50 flex items-center shadow-lg">
          <div className={`px-4 py-3 rounded-lg border flex items-center gap-3 ${
            toastMsg.type === 'error' ? 'bg-error-container text-error border-error/30' : 
            toastMsg.type === 'warn' ? 'bg-amber-500/20 text-amber-500 border-amber-500/30' : 
            'bg-emerald-500/15 text-emerald-500 border-emerald-500/30'
          }`}>
            <span className="text-sm font-semibold">{toastMsg.msg}</span>
          </div>
        </div>
      )}
    </div>
  );
}
